/* SENTINEL-X — personnel/operations are simulated; the real basemap uses the managed Maps proxy. */
const VIEWS={command:'COMMAND CENTER',personnel:'SOLDIER INTELLIGENCE',environment:'ENVIRONMENT & DIGITAL TWIN',infrastructure:'INFRASTRUCTURE & CYBER',intelligence:'AI INTELLIGENCE',rescue:'WHAT-IF & RESCUE'};
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const clamp=(n,min=0,max=100)=>Math.max(min,Math.min(max,n));
const round=n=>Math.round(Number(n)||0);
const clock=()=>new Date().toLocaleTimeString('en-GB',{hour12:false});
const timeAgo=(seconds=0)=>new Date(Date.now()-seconds*1000).toLocaleTimeString('en-GB',{hour12:false});
const safeText=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const randomDelta=()=>Math.round((Math.random()-.5)*2);
const idLabel=id=>String(id).replace(/[^a-z0-9-]/gi,'');
const icon=(symbol)=>`<span aria-hidden="true">${symbol}</span>`;

function createPeople(){
  const people=[];
  for(let i=1;i<=24;i++){
    const n=String(i).padStart(2,'0');
    const attention=[4,10,16,21].includes(i);
    people.push({id:`PERSONNEL-${n}`,status:'NORMAL',heartRate:attention?91+(i%9):72+(i%12),fatigue:attention?53+(i%15):22+(i%18),temperature:attention?37.4:36.5+(i%5)*.1,movement:attention?'MOVING':'MOVING',communication:attention?'FAIR':'GOOD',commQuality:attention?58:88+(i%9),risk:attention?42:27,location:{x:17+(i*17)%68,y:25+(i*23)%55},team:'ALPHA'});
  }
  people[6]={id:'PERSONNEL-07',status:'ATTENTION',heartRate:118,fatigue:74,temperature:37.6,movement:'NO MOVEMENT',communication:'WEAK',commQuality:31,risk:68,location:{x:63,y:49},team:'ALPHA'};
  return people;
}
function createEquipment(){return [
  {id:'Sensor E-01',health:98,temperature:36,runtime:'142h',failureProbability:6,status:'HEALTHY',maintenance:'82h',location:{x:31,y:30}},
  {id:'Communication Node C-04',health:94,temperature:49,runtime:'386h',failureProbability:24,status:'WARNING',maintenance:'18h',location:{x:73,y:31}},
  {id:'Vehicle Unit V-07',health:99,temperature:41,runtime:'96h',failureProbability:9,status:'HEALTHY',maintenance:'66h',location:{x:44,y:66}},
  {id:'Power System P-02',health:93,temperature:54,runtime:'521h',failureProbability:17,status:'ATTENTION',maintenance:'32h',location:{x:22,y:46}},
  {id:'Equipment E-04',health:71,temperature:68,runtime:'611h',failureProbability:62,status:'WARNING',maintenance:'18–26h',location:{x:62,y:68}}
]}
function initialAlerts(){return [
  {id:'A-104',severity:'CRITICAL',title:'Silent distress detected',source:'Personnel-07',message:'Elevated physiological stress + communication degradation.',confidence:94,time:timeAgo(18),status:'ACTIVE',action:'Assess signals and review Digital Guardian.'},
  {id:'A-103',severity:'HIGH',title:'Communication anomaly',source:'Sector B',message:'Packet loss increased to 31%. Alternate channel suggested.',confidence:91,time:timeAgo(79),status:'ACTIVE',action:'Review node health and alternate coverage.'},
  {id:'A-102',severity:'MEDIUM',title:'Equipment degradation',source:'Sensor Unit E-04',message:'Predicted failure probability: 62%. Thermal degradation pattern.',confidence:88,time:timeAgo(201),status:'ACTIVE',action:'Schedule inspection in the next safe maintenance window.'},
  {id:'A-101',severity:'MEDIUM',title:'Environmental risk',source:'Sector B',message:'Terrain stability decreasing; visibility remains under observation.',confidence:82,time:timeAgo(344),status:'ACTIVE',action:'Review environment layers and scenario controls.'}
]}
function createState(){
  return {view:'command',lastSync:clock(),livePaused:false,feedTicks:0,people:createPeople(),equipment:createEquipment(),env:{visibility:78,temperature:31,rainfall:28,terrainStability:78,weather:'Changing',environmentRisk:24},comm:{coverage:87,latency:42,packetLoss:4.2,health:87,offlineResilience:true},mission:{safety:82,teamRisk:34,missionRisk:42,responsePriority:'MEDIUM',cascadeRisk:72},alerts:initialAlerts(),events:[
    {time:timeAgo(1260),title:'Communication degradation — Sector B',level:'HIGH',source:'Comms monitor'},
    {time:timeAgo(2840),title:'Equipment overheating — E-04',level:'MEDIUM',source:'Predictive maintenance'},
    {time:timeAgo(4930),title:'Environmental visibility decline',level:'LOW',source:'Digital twin'},
    {time:timeAgo(7140),title:'Personnel fatigue event',level:'MEDIUM',source:'Digital Guardian'}
  ],layers:{terrain:true,weather:false,temp:false,visibility:false,hazard:true,infrastructure:true,personnel:true,coverage:false,teams:true,communication:true},selected:{type:'person',id:'PERSONNEL-07'},demo:{running:false,paused:false,index:0,elapsed:0},whatIf:{communication:57,equipment:80,visibility:60,result:null},beforeAfter:null,assistantOpen:false,assistantMessages:[],acknowledged:0,toastSeq:0,adminOpen:false,envBefore:null};
}
let state=createState();

function equipmentRisk(){return round(100-(state.equipment.reduce((a,e)=>a+e.health,0)/state.equipment.length));}
function commDegradation(){return clamp(100-state.comm.coverage);}
function individualRisk(person){
  const hrStress=clamp((person.heartRate-70)*1.25);
  const commStress=clamp(100-person.commQuality);
  const immobility=person.movement==='NO MOVEMENT'?100:18;
  const envStress=clamp(state.env.environmentRisk);
  return clamp(round(16+.22*hrStress+.18*person.fatigue+.15*commStress+.13*immobility+.08*envStress));
}
function derive(){
  state.people.forEach(p=>p.risk=individualRisk(p));
  const avg=state.people.reduce((a,p)=>a+p.risk,0)/state.people.length;
  const eq=equipmentRisk(), comm=commDegradation(), env=state.env.environmentRisk;
  const highest=Math.max(...state.people.map(p=>p.risk));
  const cascade=clamp(round(25.5+.58*highest+.2*comm+.18*env));
  const team=clamp(round(10+.45*avg+.25*comm+.20*env+.10*eq));
  const mission=clamp(round(13.7+.35*team+.20*eq+.18*comm+.15*env+.12*cascade));
  state.mission.cascadeRisk=cascade;state.mission.teamRisk=team;state.mission.missionRisk=mission;state.mission.safety=clamp(round(100-mission*.43));
  state.comm.health=clamp(round(state.comm.coverage*.78+(100-state.comm.packetLoss*4)*.22));
  state.comm.latency=Math.max(24,round(25+(100-state.comm.coverage)*1.25+state.comm.packetLoss*1.15));
  const priority=mission>=68||highest>=82?'CRITICAL':mission>=50||highest>=78?'HIGH':mission>=32||highest>=50?'MEDIUM':'LOW';
  state.mission.responsePriority=priority;
}
function chip(status){const s=String(status||'NORMAL').toUpperCase();let cl='';if(['ATTENTION','WARNING','WATCH','MEDIUM'].includes(s))cl='amber';if(['CRITICAL','HIGH'].includes(s))cl='red';if(['STABLE','HEALTHY','OPERATIONAL','NORMAL','SECURE','LOW','ACTIVE'].includes(s))cl='';if(s==='OPTIMIZED')cl='blue';return `<span class="state-chip ${cl}">${safeText(s)}</span>`}
function tag(status){const s=String(status||'NORMAL').toLowerCase();return `<span class="status-tag ${safeText(s)}">${safeText(s.toUpperCase())}</span>`}
function panel(title,body,opts={}){return `<section class="panel ${opts.className||''}"><div class="panel-head"><div class="panel-title"><div><h2>${title}</h2>${opts.subtitle?`<p>${opts.subtitle}</p>`:''}</div></div>${opts.right||''}</div>${body}</section>`}
function pageHead(kicker,title,subtitle,actions=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="head-actions"><span class="updated-label">UPDATED ${state.lastSync}</span>${actions}</div></div>`}
function riskStatus(r){return r>=70?'CRITICAL':r>=50?'HIGH':r>=32?'ELEVATED':'STABLE'}
function priorityColor(p){return p==='CRITICAL'?'critical':p==='HIGH'?'warn':''}

function render(){
  derive();
  $('#last-sync').textContent=state.lastSync;
  $('#feed-state').textContent=state.livePaused?'PAUSED':'STREAMING';
  $('#feed-toggle').textContent=state.livePaused?'RESUME FEED':'PAUSE FEED';
  $('#notification-count').textContent=state.alerts.filter(a=>a.status==='ACTIVE').length;
  $('#crumb-current').textContent=VIEWS[state.view]||'COMMAND CENTER';
  $$('.nav-link').forEach(n=>n.classList.toggle('active',n.dataset.view===state.view));
  document.title=`SENTINEL-X — ${VIEWS[state.view]||'Command Center'}`;
  const root=$('#app');
  const page=state.view==='command'?renderCommand():state.view==='personnel'?renderPersonnel():state.view==='environment'?renderEnvironment():state.view==='infrastructure'?renderInfrastructure():state.view==='intelligence'?renderIntelligence():renderRescue();
  root.innerHTML=page;
  if(state.demo.running)$('#demo-banner-slot')?.replaceWith(createDemoBanner());
  renderAssistant();
}

function renderKpis(){const m=state.mission,p=state.people.filter(x=>x.status==='NORMAL').length,a=state.people.filter(x=>x.status==='ATTENTION').length,c=state.people.filter(x=>x.status==='CRITICAL').length;
  return `<div class="kpi-grid">
    <div class="kpi-card" data-view="intelligence"><div class="kpi-top">MISSION SAFETY <span class="kpi-icon">◈</span></div><div class="kpi-value">${m.safety}<small> / 100</small></div><div class="kpi-bottom">Protective outlook ${chip(riskStatus(m.missionRisk)==='STABLE'?'STABLE':'ELEVATED')}</div></div>
    <div class="kpi-card" data-view="intelligence"><div class="kpi-top">TEAM RISK <span class="kpi-icon">⌘</span></div><div class="kpi-value">${m.teamRisk}<small>%</small></div><div class="kpi-bottom">Combined signal ${chip(m.teamRisk<40?'MONITOR':'HIGH')}</div></div>
    <div class="kpi-card" data-view="personnel"><div class="kpi-top">PERSONNEL <span class="kpi-icon">◉</span></div><div class="kpi-value">${state.people.length}</div><div class="kpi-bottom">${p} NORMAL / ${a} ATTENTION${c?` / ${c} CRITICAL`:''} ${tag(a?'attention':'healthy')}</div></div>
    <div class="kpi-card" data-view="infrastructure"><div class="kpi-top">EQUIPMENT <span class="kpi-icon">▧</span></div><div class="kpi-value">${round(state.equipment.reduce((n,e)=>n+e.health,0)/state.equipment.length)}<small>%</small></div><div class="kpi-bottom">Fleet health ${tag('healthy')}</div></div>
    <div class="kpi-card" data-view="infrastructure"><div class="kpi-top">COMMUNICATION <span class="kpi-icon">⌁</span></div><div class="kpi-value">${state.comm.health}<small>%</small></div><div class="kpi-bottom">${state.comm.latency}ms latency ${chip(state.comm.health>=82?'STABLE':'WATCH')}</div></div>
    <div class="kpi-card" data-view="environment"><div class="kpi-top">ENVIRONMENT <span class="kpi-icon">⌖</span></div><div class="kpi-value">${round(100-state.env.environmentRisk)}<small>%</small></div><div class="kpi-bottom">Condition index ${chip(state.env.environmentRisk<32?'WATCH':'ELEVATED')}</div></div>
  </div>`
}
function createDemoBanner(){const names=['Normal mission','Communication anomaly','Predictive equipment warning','Environment change','Silent distress','CASCADEGUARD','Rescue response brain','What-If: restore communications','Final Command Center'];const stage=state.demo.index+1;const pct=state.demo.running?Math.min(100,((state.demo.index*20+state.demo.elapsed/60*20)/180)*100):0;return `<div class="demo-banner fade-in"><div class="demo-stage-icon">${state.demo.running?'▶':'✓'}</div><div class="demo-stage-copy"><strong>DEMO MODE · STAGE ${stage} OF 9 — ${names[state.demo.index]||'Complete'}</strong><span>${state.demo.running?'Scripted safety scenario · simulated data only':'Scenario complete · review the updated mission state'}</span></div><div class="demo-progress"><div class="demo-progress-top"><span>${Math.floor(pct)}% COMPLETE</span><span>${state.demo.running?`${Math.floor((state.demo.index*20+state.demo.elapsed/60*20)/60)}:${String(Math.floor((state.demo.index*20+state.demo.elapsed/60*20)%60)).padStart(2,'0')}`:'DONE'}</span></div><div class="meter-line"><span style="width:${pct}%"></span></div></div><button class="btn small ghost" data-action="${state.demo.running?(state.demo.paused?'resume-demo':'pause-demo'):'reset-demo'}">${state.demo.running?(state.demo.paused?'RESUME':'PAUSE'):'RESET'}</button>${state.demo.running?'<button class="btn small ghost" data-action="next-stage">NEXT</button>':''}</div>`}
function renderCommand(){
  const critical=state.people.find(p=>p.id==='PERSONNEL-07');
  const activeAlerts=state.alerts.filter(a=>a.status==='ACTIVE').slice(0,4);
  const demo=state.demo.running||state.demo.index===8;
  const stage=demo?createDemoBanner():'';
  const right=`<span class="live-label"><i></i> LIVE SIMULATION</span>`;
  return `${pageHead('SENTINEL-X / ADMIN CONSOLE','Command Center','See the risk before it becomes the emergency.',`<button class="btn primary" data-action="run-demo">▶ &nbsp; RUN DEMO</button><button class="btn ghost" data-action="reset-sim">↺ RESET</button>`)}
    <div class="admin-ribbon"><span class="status-dot"></span><strong>ADMIN CONSOLE</strong><span>·</span><span>MISSION DELTA-07</span><span class="ribbon-spacer"></span><span class="sim-note">AI-GENERATED SIMULATION · NO LIVE PERSONNEL / SENSOR FEEDS</span><span class="state-chip">OPERATOR VIEW</span></div>
    ${stage}
    ${renderKpis()}
    <div class="dashboard-grid">
      ${renderMapPanel('command',right)}
      ${renderAlertsPanel(activeAlerts)}
    </div>
    <div class="lower-grid">
      ${panel('WHY RISK IS CHANGING',`<div class="panel-body"><div class="explain-row"><span class="explain-icon">△</span><div class="risk-reason"><strong>Mission risk ${state.mission.missionRisk}% · ${riskStatus(state.mission.missionRisk)}</strong><br>${missionExplanation()}<div class="factor-list">${factorBars()}</div></div></div></div>`,{subtitle:'Explainable simulation · confidence 91%'})}
      ${renderCascadePanel()}
    </div>
    <div class="lower-grid">${renderPriorityPanel()}${renderRecommendationPanel()}</div>
  `
}
function missionExplanation(){const p=state.people.reduce((a,b)=>a.risk>b.risk?a:b);const comm=state.comm.health<80?' while communication coverage is degraded':'';return `${p.id} carries the highest individual risk (${p.risk}%)${comm}. Equipment E-04 and environmental visibility are contributing signals. This is an AI-generated simulation, not a validated forecast.`}
function factorBars(){const factors=[['Personnel stress',Math.max(5,round(state.people.find(p=>p.id==='PERSONNEL-07').risk*.32))],['Communication',round(commDegradation()*.55)],['Equipment',round(equipmentRisk()*.72)],['Environment',round(state.env.environmentRisk*.46)],['Fatigue',round(state.people.find(p=>p.id==='PERSONNEL-07').fatigue*.28)],['History',6]];return factors.map(([n,v])=>`<div class="factor-row"><span>${n}</span><span class="factor-track"><span class="factor-fill" style="width:${clamp(v)}%"></span></span><span class="factor-val">${v}%</span></div>`).join('')}
function renderMapPanel(context='command',right=''){
  const marker=state.selected;
  const person=state.people.find(p=>p.id===marker?.id)||state.people.find(p=>p.id==='PERSONNEL-07');
  const equipment=state.equipment.find(e=>e.id===marker?.id);
  const isEquipment=marker?.type==='equipment'&&equipment;
  const selection=isEquipment?`<span class="selection-mark">▧</span><div class="selection-copy"><strong>${safeText(equipment.id.toUpperCase())} · ${equipment.status}</strong><span>Health ${equipment.health}% · predicted failure ${equipment.failureProbability}% · thermal ${equipment.temperature}°C</span></div><div class="selection-metrics"><div>RUNTIME<b>${equipment.runtime}</b></div><div>WINDOW<b>${equipment.maintenance}</b></div></div>`:`<span class="selection-mark">◉</span><div class="selection-copy"><strong>${safeText(person.id)} · ${person.status}</strong><span>${person.movement==='NO MOVEMENT'?'No movement detected':'Signal active'} · ${person.communication} link · Digital Guardian active</span></div><div class="selection-metrics"><div>RISK<b>${person.risk}%</b></div><div>HEART RATE<b>${person.heartRate} BPM</b></div><div>FATIGUE<b>${person.fatigue}%</b></div></div>`;
  const tools=['terrain','weather','temp','visibility','hazard','infrastructure','personnel','coverage'];
  return `<section class="panel map-panel"><div class="panel-head"><div class="panel-title"><div><h2>${context==='environment'?'DIGITAL TWIN · ENVIRONMENTAL LAYERS':'LIVE MISSION MAP'}</h2><p>Sector Delta-07 · simulated coordinates · ${clock()} local</p></div></div><div class="map-heading-meta">${right||'<span class="live-label"><i></i> SIM FEED</span>'}</div></div><div class="panel-body" style="padding:0"><div class="layer-row" style="padding:8px 10px 0">${tools.map(t=>`<button class="layer-toggle ${state.layers[t]?'on':''}" data-layer="${t}">${({terrain:'TERRAIN',weather:'WEATHER',temp:'TEMP',visibility:'VISIBILITY',hazard:'HAZARDS',infrastructure:'ASSETS',personnel:'PEOPLE',coverage:'COVERAGE'})[t]}</button>`).join('')}</div><div class="map-wrap ${state.layers.weather?'layer-weather':''} ${state.layers.hazard?'layer-hazard':''} ${state.layers.coverage?'layer-coverage':''}"><svg class="terrain-lines" viewBox="0 0 800 320" preserveAspectRatio="none" aria-hidden="true"><path d="M-30 76 C82 9 115 110 222 79S340 24 444 73 566 86 653 39 762 34 834 56"/><path d="M-30 94 C95 24 146 137 250 100S340 57 452 95 579 104 668 59 771 53 834 73"/><path d="M-30 233 C85 188 142 271 241 229S377 178 460 220 589 259 676 205 774 206 834 224"/><path d="M-20 254 C91 209 144 288 249 247S379 201 470 240 592 277 686 224 778 224 830 241"/><path class="boundary" d="M252 0 271 320M534 0 514 320M0 161 800 151"/><path class="route" d="M105 228 C187 205 205 144 298 156 S409 230 494 191 603 104 693 117"/><path class="route" d="M105 228 Q170 274 269 245 T470 246"/></svg><div class="scan-line"></div><div class="zone safe"></div><div class="zone hazard"></div><span class="map-label sector-a">SECTOR A · NORTH RIDGE</span><span class="map-label sector-b">SECTOR B · LOWLAND</span><span class="map-label safe-lab">SAFE ZONE · ALPHA</span><span class="map-label haz-lab">HAZARD ZONE · WATCH</span>
  ${state.layers.personnel?state.people.filter((p,i)=>i%2===0||p.id==='PERSONNEL-07').map((p,i)=>`<button class="map-marker person ${p.id==='PERSONNEL-07'?'warn':''} ${p.status==='CRITICAL'?'critical':''} ${marker?.id===p.id?'selected':''} ${p.location.x>70?'left-label':''}" style="left:${p.location.x}%;top:${p.location.y}%" data-marker="person" data-id="${p.id}" aria-label="Open ${p.id} marker"><span class="marker-core"></span>${p.id==='PERSONNEL-07'||i===2?`<span class="marker-label">${p.id.replace('PERSONNEL-','P-')}</span>`:''}</button>`).join(''):''}
  ${state.layers.infrastructure?state.equipment.map(e=>`<button class="map-marker equipment ${marker?.id===e.id?'selected':''} ${e.location.x>65?'left-label':''}" style="left:${e.location.x}%;top:${e.location.y}%" data-marker="equipment" data-id="${safeText(e.id)}" aria-label="Open ${safeText(e.id)} marker"><span class="marker-core"></span><span class="marker-label">${safeText(e.id.replace('Equipment ','E-').replace('Communication Node ','C-'))}</span></button>`).join(''):''}
  ${state.layers.coverage?`<button class="map-marker node" style="left:46%;top:39%" data-marker="node" data-id="NODE-C-04" aria-label="Communication node"><span class="marker-core"></span><span class="marker-label">NODE C-04</span></button>`:''}<span class="map-coord">SIM GRID · 34° N / 117° W</span></div><div class="map-legend"><span class="legend-item"><i class="legend-dot"></i> PERSONNEL</span><span class="legend-item"><i class="legend-dot attention"></i> ATTENTION</span><span class="legend-item"><i class="legend-diamond"></i> EQUIPMENT</span><span class="legend-item"><i class="legend-safe"></i> SAFE ZONE</span><span class="map-meta-end">SIMULATED OVERLAY</span></div><div class="map-selection">${selection}<button class="btn small ghost" data-action="open-guardian" data-id="${safeText(isEquipment?equipment.id:person.id)}">${isEquipment?'DETAILS':'DIGITAL GUARDIAN'} ↗</button></div></div></section>`
}
function renderAlertsPanel(alerts=state.alerts.filter(a=>a.status==='ACTIVE').slice(0,5)){
 const activeTotal=state.alerts.filter(a=>a.status==='ACTIVE').length;
 return `<section class="panel alert-panel"><div class="panel-head"><div class="panel-title"><span class="sev critical">LIVE AI ALERTS</span></div><span class="state-chip red">${activeTotal} ACTIVE</span></div><div class="alert-list">${alerts.length?alerts.map(a=>`<article class="alert-card" data-alert="${a.id}"><div class="alert-top"><span class="sev ${a.severity.toLowerCase()}">${a.severity}</span><time class="alert-time">${a.time}</time></div><h3>${safeText(a.title)}</h3><div class="alert-source">${safeText(a.source)}</div><p class="alert-message">${safeText(a.message)}</p><div class="alert-meta"><span>AI CONFIDENCE <b class="confidence">${a.confidence}%</b></span><span>${a.status}</span></div><div class="alert-actions"><button class="btn small" data-action="investigate" data-id="${a.id}">INVESTIGATE</button><button class="btn small" data-action="simulate-alert" data-id="${a.id}">SIMULATE</button><button class="btn small ghost" data-action="dismiss-alert" data-id="${a.id}">DISMISS</button></div></article>`).join(''):`<div class="empty-state"><strong>All clear for now</strong>No active simulated alerts. Telemetry continues to update.</div>`}</div><div class="alert-footer"><button class="link-button" data-view="intelligence">OPEN ALERT HISTORY &nbsp;↗</button></div></section>`
}
function renderCascadePanel(){const chain=['Communication degradation','Delayed personnel signal','Reduced situational awareness','Delayed distress detection','Team risk increases','Response priority increases'];return panel('CASCADEGUARD',`<div class="panel-body"><div class="panel-kicker">PREDICTING HOW SMALL ANOMALIES BECOME LARGER RISKS</div><div class="chain">${chain.map((n,i)=>`${i?'<span class="chain-arrow">›</span>':''}<div class="chain-node ${i>=3?'warn':''}">${n}</div>`).join('')}</div><div class="cascade-summary"><div><div class="cascade-num">${state.mission.cascadeRisk}%</div><div class="cascade-label">CASCADE RISK</div></div><div class="cascade-note"><div class="cascade-label"><b>EARLY WARNING</b>Current anomalies may combine into a higher-risk event.</div></div><button class="btn small warn" data-action="intervene">INTERVENE NOW</button></div></div>`,{subtitle:'Weak signals · causal chain'})}
function priorityIncidents(){const p=state.people.find(p=>p.id==='PERSONNEL-07');return [
  {id:p.id,severity:p.risk>65?'CRITICAL':'HIGH',score:Math.min(99,round(28+p.risk)),reason:'Physiological stress + communication loss + immobility detected.'},
  {id:'Communication Node C-04',severity:state.comm.health<80?'HIGH':'MEDIUM',score:round(50+commDegradation()),reason:`Network health ${state.comm.health}% · ${round(state.comm.packetLoss)}% packet loss trend.`},
  {id:'Equipment E-04',severity:'MEDIUM',score:round(state.equipment.find(e=>e.id==='Equipment E-04').failureProbability-8),reason:'Thermal degradation pattern; inspection window approaching.'},
  {id:'Environmental Zone B',severity:'LOW',score:round(state.env.environmentRisk+7),reason:'Visibility and terrain stability require monitoring.'}
].sort((a,b)=>b.score-a.score)}
function renderPriorityPanel(){return panel('RESPONSE PRIORITY',`<div class="panel-body"><div class="panel-kicker">AI RESCUE RESPONSE BRAIN · HUMAN REVIEW REQUIRED</div>${priorityIncidents().map((x,i)=>`<div class="incident-row"><span class="rank">${String(i+1).padStart(2,'0')}</span><div><strong>${safeText(x.id)} <span class="status-tag ${x.severity.toLowerCase()}">${x.severity}</span></strong><small>${safeText(x.reason)}</small></div><span class="priority-score ${x.severity==='CRITICAL'?'critical':''}">${x.score}</span></div>`).join('')}<div class="attention-banner" style="margin-top:9px">Priority ranks are simulated guidance. Operator review is required before any action.</div></div>`,{subtitle:`Overall response priority · ${state.mission.responsePriority}`})}
function renderRecommendationPanel(){const recs=[['RECOMMENDATION 01','Establish alternate communication channel for Personnel-07.','Risk reduction','-12%','89%'],['RECOMMENDATION 02','Dispatch nearby support team to investigate Personnel-07.','Response time','-18%','86%'],['RECOMMENDATION 03','Inspect Equipment E-04 during next safe maintenance window.','Failure risk','-21%','84%']];return panel('RECOMMENDED ACTIONS',`<div class="panel-body">${recs.map((r,i)=>`<div class="recommendation"><div class="rec-head"><span>${r[0]}</span><span class="state-tag">${i===0?'HUMAN APPROVAL':''}</span></div><div class="rec-body">${r[1]}</div><div class="rec-meta"><span>${r[2]} <b>${r[3]}</b></span><span>CONFIDENCE <b>${r[4]}</b></span><button class="link-button" data-action="review-recommendation" data-index="${i}">REVIEW & APPROVE ↗</button></div></div>`).join('')}<div class="panel-kicker" style="margin-top:9px">SIMULATED OUTCOME ONLY · OPERATOR APPROVAL REQUIRED</div></div>`,{subtitle:'Decision support, not autonomous actions'})}

function renderPersonnel(){return `${pageHead('PERSONNEL / DIGITAL GUARDIAN','Soldier Intelligence','Wearable signals and communication status — simulated, not connected to people.',`<button class="btn primary" data-action="open-guardian" data-id="PERSONNEL-07">OPEN DIGITAL GUARDIAN</button>`)}<div class="section-grid" style="margin-bottom:12px">${panel('TEAM ALPHA · LIVE ROSTER',`<div class="panel-body"><div class="mini-stat-grid"><div class="mini-stat"><span>PERSONNEL</span><strong>${state.people.length}</strong><small>Roster size</small></div><div class="mini-stat"><span>NORMAL</span><strong>${state.people.filter(p=>p.status==='NORMAL').length}</strong><small>Monitoring</small></div><div class="mini-stat"><span>ATTENTION</span><strong style="color:var(--amber)">${state.people.filter(p=>p.status==='ATTENTION').length}</strong><small>Review signals</small></div></div><div class="divider"></div><div class="status-line"><i class="status-dot"></i> Digital Guardian active · local simulation</div></div>`,{subtitle:'24 simulated personnel'})}${panel('TEAM RISK · EXPLAINABLE',`<div class="panel-body"><div class="split-label"><span>COMBINED TEAM RISK</span><b class="confidence">${state.mission.teamRisk}%</b></div><div class="risk-meter" style="margin-top:8px"><span style="width:${state.mission.teamRisk}%"></span></div><div class="mini-legend" style="margin-top:9px"><span>● 19 Normal</span><span style="color:var(--amber)">● 4 Attention</span><span style="color:var(--red)">● 1 Critical signal</span></div><div class="quote-callout">One elevated individual signal can affect overall team risk when communications are degraded.</div></div>`,{subtitle:'TEAM ALPHA · derived from shared state'})}</div><div class="people-grid">${state.people.map(p=>`<article class="person-card" data-person="${p.id}"><div class="person-card-top"><div><div class="person-id">${p.id}</div><div class="person-sub">Sector ${p.location.x>55?'B':'A'} · ${p.team}</div></div>${tag(p.status)}</div><div class="risk-row"><div><span class="risk-big" style="color:${p.risk>=65?'var(--amber)':p.risk>=48?'#e9c477':'var(--text)'}">${p.risk}%</span><div class="person-sub">AI RISK SCORE</div></div><span class="risk-word">${p.risk>=65?'REVIEW':p.risk>=45?'WATCH':'NORMAL'}</span></div><div class="meter-line"><span style="width:${p.risk}%;background:${p.risk>=65?'var(--amber)':'var(--cyan)'}"></span></div><div class="person-metrics"><div>HEART RATE<b>${p.heartRate} BPM</b></div><div>FATIGUE<b>${p.fatigue}%</b></div><div>TEMPERATURE<b>${p.temperature.toFixed(1)}°C</b></div><div>COMMUNICATION<b>${p.communication}</b></div><div>MOVEMENT<b>${p.movement}</b></div><div>LOCATION<b>${p.location.x} · ${p.location.y}</b></div></div><p class="person-explain">${p.id==='PERSONNEL-07'?'Multiple weak signals indicate possible distress.':'Signals within the simulated monitoring range.'}</p><button class="btn small ghost" data-action="open-guardian" data-id="${p.id}">OPEN DIGITAL GUARDIAN ↗</button></article>`).join('')}</div>`}
function guardianModal(id){const p=state.people.find(x=>x.id===id)||state.people.find(x=>x.id==='PERSONNEL-07');const factors=[['Heart rate',22],['Fatigue',18],['Communication loss',15],['No movement',13],['Environmental conditions',8]];return openModal(`DIGITAL GUARDIAN · ${p.id}`,`<div class="status-line">${tag(p.status)} <span>Digital Guardian: ACTIVE · simulated wearable</span></div><div class="divider"></div><div class="timeline">${[['14:29','Normal movement','Location pings stable'],['14:30','Heart rate increasing',`${p.heartRate} BPM · above simulated baseline`],['14:31','Communication weakening',`${p.communication} link · ${p.commQuality}% signal quality`],['14:32','No movement detected',p.movement],['14:32','Silent distress probability increased','Multiple weak signals coincide'],['14:32','AI alert generated','Confidence 94% · simulation-based']].map((t,i)=>`<div class="timeline-item ${i>=3?'alert':''}"><time>${t[0]}</time><strong>${t[1]}</strong><p>${safeText(t[2])}</p></div>`).join('')}</div><div class="divider"></div><div class="split-label"><span>INDIVIDUAL RISK</span><b class="confidence">${p.risk}%</b></div><div class="risk-meter" style="margin:7px 0 11px"><span style="width:${p.risk}%"></span></div><strong style="font-size:8px">WHY? · SIGNAL CONTRIBUTIONS</strong><div class="graph-bars" style="margin-top:8px">${factors.map(([n,v])=>`<div class="graph-row"><span>${n}</span><div class="graph-track"><span style="width:${v*3}%"></span></div><b>+${v}%</b></div>`).join('')}</div><p class="panel-kicker" style="margin-top:11px">AI-GENERATED SIMULATION · NOT A CLINICAL OR OPERATIONAL ASSESSMENT</p>`,[{label:'Close',action:'close',className:'ghost'},{label:'Investigate signal',action:'investigate-person',id:p.id,className:'primary'}])}

function environmentalControls(){return `<div class="panel-body">${[['temperature','Temperature',state.env.temperature,10,45,'°C'],['rainfall','Rainfall',state.env.rainfall,0,100,'%'],['visibility','Visibility',state.env.visibility,0,100,'%'],['terrainStability','Terrain stability',state.env.terrainStability,0,100,'%'],['coverage','Communication coverage',state.comm.coverage,0,100,'%']].map(([k,n,v,min,max,unit])=>`<div class="slider-row"><label for="env-${k}">${n}<span class="range-sub">${k==='coverage'?'Network signal':k==='terrainStability'?'Terrain condition':'Scenario input'}</span></label><input id="env-${k}" type="range" min="${min}" max="${max}" value="${v}" data-env-field="${k}" aria-label="${n}"><output id="out-${k}">${v}${unit}</output></div>`).join('')}<div class="action-row"><button class="btn primary" data-action="simulate-environment">SIMULATE ENVIRONMENT</button><button class="btn ghost" data-action="reset-env">RESET VALUES</button></div><div class="panel-kicker" style="margin-top:9px">SLIDERS ARE LOCAL SCENARIO INPUTS · NO EXTERNAL ENVIRONMENT FEED</div></div>`}
function renderEnvironment(){return `${pageHead('ENVIRONMENT / DIGITAL TWIN','Environment & Digital Twin','Explore simulated terrain, weather, visibility and safety layers.',`<button class="btn primary" data-action="simulate-environment">RUN ENVIRONMENT SIMULATION</button>`)}<div class="section-grid" style="grid-template-columns:minmax(0,1.45fr) minmax(280px,.8fr);align-items:start;margin-bottom:12px">${renderMapPanel('environment')}<div class="stack">${panel('DIGITAL TWIN · CURRENT CONDITIONS',`<div class="panel-body"><div class="mini-stat-grid" style="grid-template-columns:1fr 1fr"><div class="mini-stat"><span>TERRAIN CONDITION</span><strong style="font-size:14px">${state.env.terrainStability>65?'Stable':'Watch'}</strong><small>Stability ${state.env.terrainStability}%</small></div><div class="mini-stat"><span>VISIBILITY</span><strong>${state.env.visibility}%</strong><small>Simulated sensor</small></div><div class="mini-stat"><span>TEMPERATURE</span><strong>${state.env.temperature}°C</strong><small>Ambient estimate</small></div><div class="mini-stat"><span>WEATHER</span><strong style="font-size:14px">${state.env.weather}</strong><small>Scenario profile</small></div></div><div class="divider"></div><div class="split-label"><span>ENVIRONMENTAL RISK</span><b class="confidence">${state.env.environmentRisk}%</b></div><div class="risk-meter" style="margin-top:8px"><span style="width:${state.env.environmentRisk}%"></span></div></div>`,{subtitle:'SIMULATED CONDITIONS'})}${panel('ENVIRONMENTAL SIMULATION',environmentalControls(),{subtitle:'Adjust conditions and recalculate linked risk'})}</div></div><div class="section-grid">${panel('ACTIVE LAYERS',`<div class="panel-body"><div class="layer-row">${['terrain','weather','temp','visibility','hazard','infrastructure','personnel','coverage'].map(t=>`<button class="layer-toggle ${state.layers[t]?'on':''}" data-layer="${t}">${({terrain:'Terrain',weather:'Weather',temp:'Temperature',visibility:'Visibility',hazard:'Hazard zones',infrastructure:'Infrastructure',personnel:'Personnel',coverage:'Comm coverage'})[t]}</button>`).join('')}</div><div class="quote-callout">Layers are rendered locally over real Google Maps imagery; coordinates, personnel and risk overlays remain simulated.</div></div>`)}${panel('BEFORE / AFTER',environmentBeforeAfter(),{subtitle:'Last scenario calculation'})}</div>`}
function environmentBeforeAfter(){if(!state.beforeAfter)return `<div class="panel-body"><div class="empty-state"><strong>No environmental scenario applied</strong>Adjust the sliders and select “Simulate environment” to compare the current shared state.</div></div>`;return `<div class="panel-body"><div class="before-after">${compareCard('BEFORE',state.beforeAfter.before)}${compareCard('AFTER',state.beforeAfter.after,true)}</div></div>`}
function compareCard(title,m,after=false){return `<div class="compare-card ${after?'after':''}"><h3>${title}</h3>${Object.entries(m).map(([k,v])=>`<div class="compare-line"><span>${k}</span><b>${safeText(v)}</b></div>`).join('')}</div>`}

function renderInfrastructure(){const e04=state.equipment.find(e=>e.id==='Equipment E-04');return `${pageHead('INFRASTRUCTURE / CYBERSHIELD','Infrastructure & Cyber','Communications resilience, equipment health and defensive monitoring.',`<button class="btn ghost" data-action="refresh-feed">↻ &nbsp; REFRESH SIGNALS</button>`)}<div class="section-grid" style="grid-template-columns:repeat(2,minmax(0,1fr));margin-bottom:12px">${panel('COMMUNICATION STATUS',`<div class="panel-body"><div class="mini-stat-grid"><div class="mini-stat"><span>NETWORK HEALTH</span><strong>${state.comm.health}%</strong><small>${state.comm.health>80?'Stable':'Attention'}</small></div><div class="mini-stat"><span>LATENCY</span><strong>${state.comm.latency}<small>ms</small></strong><small>Local simulation</small></div><div class="mini-stat"><span>PACKET LOSS</span><strong>${state.comm.packetLoss.toFixed(1)}<small>%</small></strong><small>Sector B trend</small></div></div><div class="split-label" style="margin-top:13px"><span>OFFLINE RESILIENCE</span><b style="color:var(--green)">ACTIVE</b></div><div class="network-graph"><svg viewBox="0 0 400 144" aria-label="Simulated network graph"><line x1="65" y1="72" x2="151" y2="38"/><line x1="65" y1="72" x2="157" y2="109"/><line x1="151" y1="38" x2="241" y2="68"/><line x1="157" y1="109" x2="241" y2="68"/><line x1="241" y1="68" x2="337" y2="36"/><line x1="241" y1="68" x2="334" y2="111"/><circle cx="65" cy="72" r="11"/><circle cx="151" cy="38" r="9"/><circle cx="157" cy="109" r="9"/><circle class="warn" cx="241" cy="68" r="12"/><circle cx="337" cy="36" r="9"/><circle cx="334" cy="111" r="9"/><text x="43" y="101">HUB A</text><text x="133" y="20">NODE 02</text><text x="132" y="135">NODE 03</text><text x="221" y="99">C-04</text><text x="318" y="18">SECTOR B</text><text x="315" y="136">RELAY 06</text></svg></div><div class="network-legend"><span>6 simulated nodes</span><span>Node C-04 · warning</span><span>Offline resilience active</span></div></div>`,{subtitle:'Resilient links · simulated network'})}${panel('CYBERSHIELD · DEFENSIVE MONITORING',`<div class="panel-body"><div class="mini-stat-grid" style="grid-template-columns:repeat(2,1fr)"><div class="mini-stat"><span>NETWORK STATUS</span><strong style="font-size:14px;color:var(--green)">SECURE</strong></div><div class="mini-stat"><span>AUTHENTICATION</span><strong style="font-size:14px">NORMAL</strong></div><div class="mini-stat"><span>TRAFFIC</span><strong style="font-size:14px">NORMAL</strong></div><div class="mini-stat"><span>SUSPICIOUS ACTIVITY</span><strong style="font-size:14px;color:var(--green)">LOW</strong></div></div><div class="split-label" style="margin-top:12px"><span>OFFLINE MODE</span><b style="color:var(--green)">READY</b></div><div class="divider"></div><div class="event-row"><time>${clock()}</time><i class="event-pin" style="background:var(--amber)"></i><div><strong>Unexpected authentication pattern detected.</strong><span> Defensive monitor · simulated</span></div><span class="event-level">LOW</span></div><div class="event-row"><time>${timeAgo(92)}</time><i class="event-pin"></i><div><strong>Communication node temporarily unavailable.</strong><span> Node C-04 · simulated</span></div><span class="event-level">WATCH</span></div><button class="btn small warn" data-action="isolate-network">REVIEW ISOLATION RECOMMENDATION</button><p class="panel-kicker" style="margin-top:9px">DEFENSIVE MONITORING ONLY · NO CYBER ACTIONS ARE EXECUTED</p></div>`,{subtitle:'Detection and resilience only'})}</div><div class="section-grid three">${state.equipment.map(e=>panel(safeText(e.id.toUpperCase()),`<div class="panel-body"><div class="device-top">${tag(e.status)}<span class="confidence">${e.health}% HEALTH</span></div><div class="device-health"><span class="meter-line"><span style="width:${e.health}%;background:${e.health<76?'var(--amber)':'var(--cyan)'}"></span></span><span>${e.health}%</span></div><div class="device-details"><div>TEMPERATURE<b>${e.temperature}°C</b></div><div>RUNTIME<b>${e.runtime}</b></div><div>FAILURE PROBABILITY<b>${e.failureProbability}%</b></div><div>MAINTENANCE WINDOW<b>${e.maintenance}</b></div></div>${e.id==='Equipment E-04'?`<div class="quote-callout">Predicted issue: thermal degradation. Estimated time to failure: 18–26 hours. “Schedule inspection during next maintenance window.”</div><button class="btn small warn" data-action="simulate-failure" data-id="${safeText(e.id)}">SIMULATE FAILURE</button>`:''}</div>`,{subtitle:e.id==='Equipment E-04'?'PREDICTIVE MAINTENANCE':'ASSET HEALTH'})).join('')}</div>`}

function renderIntelligence(){const p=state.people.find(x=>x.id==='PERSONNEL-07');return `${pageHead('AI / RISK ENGINE','Unified AI Risk Engine','Understand how weak signals combine into safety risk.',`<button class="btn primary" data-action="run-scenario">RUN SCENARIO</button>`)}<div class="section-grid" style="grid-template-columns:1.05fr .95fr;margin-bottom:12px">${panel('RISK OVERVIEW',`<div class="panel-body"><div class="gauge-row">${[['INDIVIDUAL RISK',p.risk,'Personnel-07','var(--amber)'],['TEAM RISK',state.mission.teamRisk,'Team Alpha','var(--cyan)'],['MISSION RISK',state.mission.missionRisk,'Mission Delta-07','var(--blue)']].map(([n,v,sub,color])=>`<div class="gauge-card"><div class="gauge" style="--score:${v};--gauge-color:${color}"><span>${v}%</span></div><label>${n}</label><small>${sub}</small></div>`).join('')}</div><div class="panel-kicker" style="margin-top:11px">AI-GENERATED SIMULATION · ALL VALUES NORMALIZED 0–100</div></div>`,{subtitle:'Derived from shared simulated signals'})}${panel('EXPLAINABLE RISK ANALYSIS',`<div class="panel-body"><div class="graph-bars">${[['Personnel stress',22],['Communication',18],['Equipment',14],['Environment',11],['Fatigue',9],['Historical pattern',6]].map(([n,v])=>`<div class="graph-row"><span>${n}</span><div class="graph-track"><span style="width:${v*4}%"></span></div><b>${v}%</b></div>`).join('')}</div><div class="divider"></div><div class="risk-reason"><strong>WHY DID RISK INCREASE?</strong><br>${missionExplanation()}</div><div class="wrap-row" style="margin-top:9px"><span class="state-chip blue">CONFIDENCE: 91%</span><span class="panel-kicker">SIMULATION-BASED ANALYSIS</span></div><div class="action-row"><button class="btn small" data-action="view-evidence">VIEW EVIDENCE</button><button class="btn small primary" data-action="run-scenario">RUN SCENARIO</button></div></div>`,{subtitle:'Contribution percentages show relative signal influence'})}</div><div class="section-grid" style="margin-bottom:12px">${renderCascadePanel()}${panel('MISSION MEMORY',`<div class="panel-body"><div class="history-list">${state.events.slice(0,6).map((e,i)=>`<div class="memory-row"><span class="memory-id">EVENT #${String(42-i).padStart(3,'0')}</span><div><strong>${safeText(e.title)}</strong><p>Outcome: Response completed successfully. <br>AI lesson: Early signal combinations can raise response priority.</p></div><time class="memory-date">${e.time}</time></div>`).join('')}</div></div>`,{subtitle:'Historical simulated events · lessons learned'})}</div><div class="section-grid">${renderPriorityPanel()}${panel('SIMULATION MODEL',`<div class="panel-body"><div class="quote-callout">Individual Risk = weighted heart-rate stress + fatigue + communication degradation + immobility + environment.<br><br>Team Risk = average individual risk + communication risk + environmental risk.<br><br>Mission Risk = team risk + equipment risk + communication risk + environment risk + cascade risk.</div><div class="panel-kicker">TRANSPARENT DEMONSTRATION FORMULA · NOT OPERATIONALLY VALIDATED</div></div>`,{subtitle:'Why every score changes'})}</div>`}

function scenarioPresetButtons(){const presets=[['communication','Communication Failure'],['equipment','Equipment Failure'],['environment','Environmental Change'],['distress','Silent Distress'],['multiple','Multiple Events']];return `<div class="wrap-row">${presets.map(([id,n])=>`<button class="btn small ${id==='multiple'?'warn':''}" data-scenario="${id}">${n}</button>`).join('')}</div>`}
function whatIfValues(){return `<div class="panel-body"><div class="attention-banner">WHAT HAPPENS IF COMMUNICATION COVERAGE DROPS BY 30%?</div>${[['communication','Communication coverage',state.whatIf.communication,'%'],['equipment','Equipment health',state.whatIf.equipment,'%'],['visibility','Visibility',state.whatIf.visibility,'%']].map(([k,n,v,u])=>`<div class="slider-row"><label>${n}<span class="range-sub">Current ${k==='communication'?state.comm.coverage:k==='equipment'?round(state.equipment.reduce((a,e)=>a+e.health,0)/state.equipment.length):state.env.visibility}%</span></label><input type="range" min="0" max="100" value="${v}" data-whatif="${k}" aria-label="${n}"><output id="whatif-${k}">${v}${u}</output></div>`).join('')}<div class="action-row"><button class="btn primary" data-action="calculate-whatif">RECALCULATE WHAT-IF</button><button class="btn ghost" data-action="apply-whatif">APPLY TO SIMULATION</button></div><div class="divider"></div>${renderWhatIfCompare()}</div>`}
function calculateWhatIf(){const base={mission:state.mission.missionRisk,team:state.mission.teamRisk,priority:state.mission.responsePriority};const old={coverage:state.comm.coverage,env:state.env.environmentRisk,eq:state.equipment.map(e=>e.health)};const c=state.whatIf.communication,e=state.whatIf.equipment,v=state.whatIf.visibility;const envRisk=clamp(round((100-v)*.46+(100-state.env.terrainStability)*.22+state.env.rainfall*.16+(state.env.temperature>35?(state.env.temperature-35)*1.3:0)));const commRisk=100-c;const eqRisk=100-e;const p07=state.people.find(p=>p.id==='PERSONNEL-07');const ind=clamp(round(16+.22*clamp((p07.heartRate-70)*1.25)+.18*p07.fatigue+.15*commRisk+.13*(p07.movement==='NO MOVEMENT'?100:18)+.08*envRisk));const team=clamp(round(10+.45*((ind+state.people.filter(p=>p.id!=='PERSONNEL-07').reduce((a,p)=>a+p.risk,0))/24)+.25*commRisk+.20*envRisk+.10*eqRisk));const cascade=clamp(round(25.5+.58*Math.max(ind,...state.people.filter(p=>p.id!=='PERSONNEL-07').map(p=>p.risk))+.2*commRisk+.18*envRisk));const mission=clamp(round(13.7+.35*team+.20*eqRisk+.18*commRisk+.15*envRisk+.12*cascade));state.whatIf.result={before:{'Mission Risk':`${base.mission}%`,'Team Risk':`${base.team}%`,'Response Priority':base.priority},after:{'Mission Risk':`${mission}%`,'Team Risk':`${team}%`,'Response Priority':mission>=68?'CRITICAL':mission>=50?'HIGH':mission>=32?'MEDIUM':'LOW'},explanation:commRisk>35?'The increase is primarily caused by communication degradation combined with reduced visibility.':'The simulation shows a smaller change under the current input values.',reduction:base.mission-mission};state._whatIfOld=old;}
function renderWhatIfCompare(){const r=state.whatIf.result||{before:{'Mission Risk':`${state.mission.missionRisk}%`,'Team Risk':`${state.mission.teamRisk}%`,'Response Priority':state.mission.responsePriority},after:{'Mission Risk':'—','Team Risk':'—','Response Priority':'Select recalculate'},explanation:'Adjust the inputs and recalculate to see a scenario-specific change.',reduction:null};return `<div class="before-after">${compareCard('BEFORE',r.before)}${compareCard('AFTER',r.after,true)}</div><p class="risk-reason" style="margin:9px 0 0">${safeText(r.explanation)}${r.reduction!==null?` <b style="color:${r.reduction<0?'var(--red)':'var(--green)'}">${r.reduction<0?'+':''}${-r.reduction}% change</b>`:''}</p>`}
function renderRescue(){return `${pageHead('WHAT-IF / RESCUE RESPONSE BRAIN','What-If & Rescue','Rehearse options, compare projected risk and keep people in control.',`<button class="btn ghost" data-action="reset-sim">↺ RESET SCENARIO</button>`)}<div class="section-grid" style="grid-template-columns:1.1fr .9fr;margin-bottom:12px">${panel('WHAT-IF SIMULATION',whatIfValues(),{subtitle:'Scenario calculation · linked to current state'})}${panel('SCENARIO CONTROLS',`<div class="panel-body"><div class="panel-kicker">SELECT A SIMULATED EVENT</div>${scenarioPresetButtons()}<div class="divider"></div><div class="attention-banner">Presets update personnel, communications, equipment, environmental risk, cascade and response priority together.</div><div class="divider"></div><div class="split-label"><span>CURRENT RESPONSE PRIORITY</span>${chip(state.mission.responsePriority)}</div><div class="risk-meter" style="margin-top:8px"><span style="width:${state.mission.missionRisk}%"></span></div><div class="mini-legend" style="margin-top:8px"><span>Risk engine: ${state.mission.missionRisk}%</span><span>CascadeGuard: ${state.mission.cascadeRisk}%</span></div></div>`,{subtitle:'Full-system scenario presets'})}</div><div class="section-grid" style="grid-template-columns:1fr 1fr;margin-bottom:12px">${renderPriorityPanel()}${renderRecommendationPanel()}</div>${panel('SCENARIO EVENT HISTORY',`<div class="panel-body"><div class="history-list">${state.events.length?state.events.slice(0,7).map(e=>`<div class="event-row"><time>${e.time}</time><i class="event-pin"></i><div><strong>${safeText(e.title)}</strong><span> · ${safeText(e.source||'simulation engine')}</span></div><span class="event-level">${safeText(e.level)}</span></div>`).join(''):'<div class="empty-state">No events recorded yet.</div>'}</div></div>`,{subtitle:'Local-only simulation history'})}`}

const stageNames=['Normal mission','Communication anomaly','Predictive equipment warning','Environment change','Silent distress','CASCADEGUARD','Rescue response brain','What-If: restore communications','Final Command Center'];
function startDemo(){state=createState();state.demo.running=true;state.demo.paused=false;state.demo.index=0;state.demo.elapsed=0;state.view='command';applyDemoStage(0);notify('DEMO MODE STARTED · 9 STAGES · SIMULATION ONLY');render();}
function applyDemoStage(index){state.demo.index=index;state.demo.elapsed=0;state.demo.running=index<8;state.demo.paused=false;
  if(index===0){state.comm.coverage=96;state.comm.packetLoss=1.4;state.equipment.forEach(e=>{if(e.id==='Equipment E-04')Object.assign(e,{health:94,failureProbability:12,status:'HEALTHY'});else e.health=Math.max(e.health,90)});state.env.visibility=88;state.env.environmentRisk=12;state.people.find(p=>p.id==='PERSONNEL-07').movement='MOVING';state.people.find(p=>p.id==='PERSONNEL-07').commQuality=92;state.people.find(p=>p.id==='PERSONNEL-07').heartRate=86;state.people.find(p=>p.id==='PERSONNEL-07').fatigue=44;state.mission.safety=82;state.mission.teamRisk=24;state.alerts=[];state.view='command';}
  if(index===1){state.comm.coverage=72;state.comm.packetLoss=31;state.view='command';stageAlert('HIGH','COMMUNICATION ANOMALY DETECTED','Sector B','Coverage 96% → 72%. Mission risk signal changing from 82 → 58.',92);state.mission.missionRisk=58;}
  if(index===2){const e=state.equipment.find(e=>e.id==='Equipment E-04');Object.assign(e,{health:71,failureProbability:62,status:'WARNING',temperature:68});state.view='infrastructure';stageAlert('MEDIUM','PREDICTIVE EQUIPMENT WARNING','Equipment E-04','Health 94% → 71%. Predicted thermal degradation; failure probability 62%.',88);}
  if(index===3){state.env.visibility=61;state.env.environmentRisk=39;state.view='environment';stageAlert('MEDIUM','ENVIRONMENTAL RISK INCREASING','Sector B','Visibility 88% → 61%. Terrain and visibility layers show increased simulated risk.',84);}
  if(index===4){const p=state.people.find(p=>p.id==='PERSONNEL-07');Object.assign(p,{heartRate:118,fatigue:74,movement:'NO MOVEMENT',communication:'WEAK',commQuality:31,status:'CRITICAL'});state.view='personnel';stageAlert('CRITICAL','SILENT DISTRESS DETECTED','Personnel-07','118 BPM · no movement · weak communication. Multiple weak signals coincide.',94);}
  if(index===5){state.view='intelligence';state.mission.cascadeRisk=82;stageAlert('HIGH','CASCADEGUARD EARLY WARNING','Mission Delta-07','Communication degradation → reduced monitoring → silent distress → team risk increase.',91);}
  if(index===6){state.view='rescue';state.mission.responsePriority='HIGH';stageAlert('HIGH','RESCUE RESPONSE PRIORITY UPDATED','Personnel-07','Personnel-07 ranks CRITICAL; communication node HIGH; equipment and environment MEDIUM.',90);}
  if(index===7){state.view='rescue';state.whatIf.communication=90;state.whatIf.equipment=71;state.whatIf.visibility=61;state.beforeAfter={before:{'Mission Risk':'74%','Team Risk':'51%','Response Priority':'HIGH'},after:{'Mission Risk':'48%','Team Risk':'31%','Response Priority':'MEDIUM'}};state.whatIf.result={before:state.beforeAfter.before,after:state.beforeAfter.after,explanation:'Restoring communication coverage produces the highest immediate reduction in mission risk.',reduction:-26};state.comm.coverage=72;state.mission.missionRisk=74;state.mission.teamRisk=51;state.mission.responsePriority='HIGH';}
  if(index===8){state.view='command';state.demo.running=false;state.demo.elapsed=20;const p=state.people.find(p=>p.id==='PERSONNEL-07');p.status='ATTENTION';p.movement='MOVING';p.communication='GOOD';p.commQuality=90;p.heartRate=92;p.fatigue=58;state.comm.coverage=90;state.comm.packetLoss=4.2;state.mission.safety=88;state.mission.teamRisk=31;state.mission.missionRisk=48;state.mission.responsePriority='OPTIMIZED';state.alerts=state.alerts.filter(a=>a.status==='ACTIVE').slice(0,2);state.events.unshift({time:clock(),title:'SENTINEL-X response plan generated',level:'OPTIMIZED',source:'Demo outcome'});notify('MISSION RISK REDUCED · RESPONSE PLAN GENERATED');}
  render();if(index<8)notify(`DEMO STAGE ${index+1} · ${stageNames[index].toUpperCase()}`,index>=3?'warn':'');
}
function stageAlert(severity,title,source,message,confidence){state.alerts.unshift({id:`DEMO-${Date.now()}`,severity,title,source,message,confidence,time:clock(),status:'ACTIVE',action:'Review the simulated event and assess a human-led response.'});state.events.unshift({time:clock(),title,level:severity,source});}
function advanceDemo(){if(!state.demo.running)return;if(state.demo.index<8)applyDemoStage(state.demo.index+1);else{state.demo.running=false;state.demo.index=8;render();}}
function pauseDemo(paused){state.demo.paused=paused;render();notify(paused?'Demo paused':'Demo resumed');}

function applyScenario(id){
  state.demo.running=false;state.demo.paused=false;state.beforeAfter=null;state.whatIf.result=null;
  const p=state.people.find(p=>p.id==='PERSONNEL-07');
  if(id==='communication'){state.comm.coverage=57;state.comm.packetLoss=31;p.commQuality=31;p.communication='WEAK';p.movement='MOVING';state.view='command';stageAlert('HIGH','COMMUNICATION FAILURE SIMULATED','Sector B','Coverage reduced to 57%; personnel monitoring, team risk, mission risk, cascade and response priority recalculated.',91);}
  if(id==='equipment'){const e=state.equipment.find(e=>e.id==='Equipment E-04');Object.assign(e,{health:51,temperature:81,failureProbability:78,status:'CRITICAL'});state.view='infrastructure';stageAlert('HIGH','EQUIPMENT FAILURE SIMULATED','Equipment E-04','Thermal stress increased; equipment, mission risk and response priority recalculated.',89);}
  if(id==='environment'){state.env.visibility=46;state.env.rainfall=78;state.env.terrainStability=42;state.env.weather='Heavy rain';state.env.environmentRisk=55;state.view='environment';stageAlert('MEDIUM','ENVIRONMENTAL CHANGE SIMULATED','Sector B','Visibility and terrain stability reduced; linked mission risk recalculated.',86);}
  if(id==='distress'){Object.assign(p,{heartRate:122,fatigue:82,movement:'NO MOVEMENT',communication:'WEAK',commQuality:23,status:'CRITICAL'});state.comm.coverage=Math.min(state.comm.coverage,72);state.view='personnel';stageAlert('CRITICAL','SILENT DISTRESS SIMULATED','Personnel-07','Heart rate, fatigue, immobility and weak communications now combine in the risk model.',94);}
  if(id==='multiple'){state.comm.coverage=61;state.comm.packetLoss=22;state.env.visibility=52;state.env.environmentRisk=48;const e=state.equipment.find(e=>e.id==='Equipment E-04');Object.assign(e,{health:60,temperature:76,failureProbability:69,status:'WARNING'});Object.assign(p,{heartRate:112,fatigue:78,movement:'NO MOVEMENT',communication:'WEAK',commQuality:29,status:'CRITICAL'});state.view='command';stageAlert('CRITICAL','MULTIPLE SIGNALS COMBINED','Mission Delta-07','Communication, equipment, environment and personnel signals changed together; all dashboards recalculated.',93);}
  derive();render();notify(`${id.toUpperCase()} SCENARIO APPLIED · SHARED STATE UPDATED`,'warn');
}
function applyEnvironment(){const before={...state.env,coverage:state.comm.coverage};state.env.environmentRisk=clamp(round((100-state.env.visibility)*.42+(100-state.env.terrainStability)*.26+state.env.rainfall*.18+(state.env.temperature>35?(state.env.temperature-35)*1.1:0)));state.env.weather=state.env.rainfall>70?'Heavy rain':state.env.rainfall>45?'Showers':'Changing';derive();const after={...state.env,coverage:state.comm.coverage};state.beforeAfter={before:{'Visibility':`${before.visibility}%`,'Temperature':`${before.temperature}°C`,'Terrain stability':`${before.terrainStability}%`,'Environment risk':`${before.environmentRisk}%`,'Team risk':`${state.mission.teamRisk}%`},after:{'Visibility':`${after.visibility}%`,'Temperature':`${after.temperature}°C`,'Terrain stability':`${after.terrainStability}%`,'Environment risk':`${after.environmentRisk}%`,'Mission risk':`${state.mission.missionRisk}%`,'Response priority':state.mission.responsePriority}};state.events.unshift({time:clock(),title:'Environmental simulation recalculated',level:'SIMULATION',source:'Digital twin'});render();notify('ENVIRONMENT SIMULATED · LINKED RISKS RECALCULATED');}
function resetEnvironment(){state.env={visibility:78,temperature:31,rainfall:28,terrainStability:78,weather:'Changing',environmentRisk:24};state.comm.coverage=87;state.beforeAfter=null;derive();render();notify('ENVIRONMENT SCENARIO RESET');}

function runWhatIf(apply=false){calculateWhatIf();if(apply){state.comm.coverage=state.whatIf.communication;const avgHealth=state.equipment.reduce((a,e)=>a+e.health,0)/state.equipment.length;const goal=state.whatIf.equipment;const delta=goal-avgHealth;state.equipment.forEach(e=>e.health=clamp(round(e.health+delta)));state.env.visibility=state.whatIf.visibility;state.env.environmentRisk=clamp(round((100-state.env.visibility)*.46+(100-state.env.terrainStability)*.22+state.env.rainfall*.16));derive();state.events.unshift({time:clock(),title:'What-If scenario applied to local simulation',level:'SIMULATION',source:'What-If'});notify('WHAT-IF APPLIED TO LOCAL SIMULATION');}else notify('WHAT-IF RECALCULATED FROM CURRENT STATE');render();}

function assistantAnswer(question){const q=question.toLowerCase();const top=priorityIncidents()[0];const person=state.people.find(p=>p.id==='PERSONNEL-07');const e=state.equipment.reduce((a,b)=>a.failureProbability>b.failureProbability?a:b);let answer;
  if(/biggest risk|highest risk|who needs|attention|distress|personnel/.test(q))answer=`${person.id} currently has the highest individual risk at ${person.risk}%. The contributing signals are ${person.heartRate} BPM, ${person.fatigue}% fatigue, ${person.communication.toLowerCase()} communication, and ${person.movement.toLowerCase()}. Review Digital Guardian before deciding what to do.`;
  else if(/why|increase|cause|evidence/.test(q))answer=`Mission risk is ${state.mission.missionRisk}% and team risk is ${state.mission.teamRisk}%. ${missionExplanation()} Key contributors are personnel stress, communications (${state.comm.health}% health), equipment and visibility.`;
  else if(/communication|coverage|fails|failure/.test(q))answer=`If coverage drops, communication degradation can delay personnel signals and reduce awareness. The linked risk engine recalculates individual, team, mission and cascade risk, then updates response priority. Current simulated coverage is ${state.comm.coverage}%. Try the Communication Failure preset to rehearse it.`;
  else if(/prioriti[sz]e|priority|respond|action/.test(q))answer=`Prioritize ${top.id} (${top.severity}, score ${top.score}) because ${top.reason} The next ranked item is ${priorityIncidents()[1].id}. Recommendations remain decision support and require human approval.`;
  else if(/equipment|asset|failure/.test(q))answer=`${e.id} is the highest-risk equipment item in the current simulation: ${e.failureProbability}% predicted failure probability, ${e.health}% health, ${e.temperature}°C. The simulated pattern suggests thermal degradation; schedule an inspection during a safe maintenance window.`;
  else answer=`Current mission risk is ${state.mission.missionRisk}% (${riskStatus(state.mission.missionRisk)}). ${missionExplanation()} I can explain the highest risk, communications scenario, response priority, or equipment status. All values are simulated.`;
  return answer;
}
function renderAssistant(){const root=$('#assistant-root');if(!root)return;root.innerHTML=`${state.assistantOpen?`<section class="assistant-panel" role="dialog" aria-label="Sentinel AI assistant"><div class="assistant-head"><div><strong>✳ SENTINEL AI</strong><small>Answers from the current simulated state · not an external AI service</small></div><button class="icon-button" data-action="assistant-close" aria-label="Close assistant">×</button></div><div class="assistant-messages" id="assistant-messages">${state.assistantMessages.length?state.assistantMessages.map(m=>`<div class="assistant-msg ${m.role==='user'?'user':''}">${safeText(m.text)}${m.role==='assistant'?'<span class="sim-mark">AI-GENERATED SIMULATION</span>':''}</div>`).join(''):'<div class="assistant-msg">I’m monitoring the current simulated state. Ask about risk, communications, personnel, priorities or equipment.<span class="sim-mark">LOCAL SIMULATION · NO LIVE SENSOR CONNECTION</span></div>'}</div><div class="assistant-prompts"><button data-question="What is the biggest risk?">Biggest risk?</button><button data-question="Why did mission risk increase?">Why risk increased?</button><button data-question="What should we prioritize?">What to prioritize?</button></div><form class="assistant-form" id="assistant-form"><input id="assistant-input" placeholder="Ask about the current state…" autocomplete="off" aria-label="Ask Sentinel AI"><button type="submit">ASK ↗</button></form></section>`:''}<button class="assistant-fab" data-action="assistant-open" aria-label="Open Sentinel AI">✳</button>`;const msgs=$('#assistant-messages');if(msgs)msgs.scrollTop=msgs.scrollHeight;}
function askAssistant(question){if(!question.trim())return;state.assistantMessages.push({role:'user',text:question.trim()},{role:'assistant',text:assistantAnswer(question)});state.assistantOpen=true;renderAssistant();}

function notify(message,type=''){const root=$('#toast-region');if(!root)return;const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;root.append(el);setTimeout(()=>el.remove(),3400);}
function openModal(title,body,actions=[]){$('#modal-root').innerHTML=`<div class="modal-backdrop" data-action="backdrop-close"><section class="modal" role="dialog" aria-modal="true" aria-label="${safeText(title)}"><header class="modal-head"><h2>${safeText(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Close">×</button></header><div class="modal-body">${body}</div><footer class="modal-actions">${actions.map(a=>`<button class="btn ${a.className||''}" data-action="${a.action||'close-modal'}" ${a.id?`data-id="${safeText(a.id)}"`:''} ${a.index!==undefined?`data-index="${a.index}"`:''}>${safeText(a.label)}</button>`).join('')}</footer></section></div>`;}
function closeModal(){$('#modal-root').innerHTML='';}
function confirmAction(title,text,confirmLabel,onConfirm,kind='primary'){openModal(title,`<p>${safeText(text)}</p><div class="attention-banner">This affects only the local prototype simulation. It does not dispatch, notify or control any real person or system.</div>`,[{label:'Cancel',action:'close-modal',className:'ghost'},{label:confirmLabel,action:'confirm-local',className:kind}]);state.pendingConfirm=onConfirm;}
function showAlertDetail(id){const a=state.alerts.find(x=>x.id===
id)||null;if(!a){notify('Alert no longer active');return}openModal(`${a.severity} ALERT · ${a.title}`,`<div class="status-line"><span class="sev ${a.severity.toLowerCase()}">${safeText(a.severity)}</span><span>${safeText(a.source)} · ${safeText(a.time)}</span></div><div class="divider"></div><p>${safeText(a.message)}</p><div class="quote-callout">${safeText(a.action||'Review simulated evidence and decide whether to investigate.')}</div><p>AI confidence: <b>${a.confidence}%</b><br>Source: local simulated feed<br>Status: ${safeText(a.status)}</p><div class="panel-kicker">AI-GENERATED SIMULATION · HUMAN REVIEW REQUIRED</div>`,[{label:'Close',action:'close-modal',className:'ghost'},{label:'Open response view',action:'open-rescue',className:'primary'}]);}
function investigatePerson(id){const p=state.people.find(x=>x.id===id);if(!p)return;state.selected={type:'person',id:p.id};state.view='personnel';closeModal();render();guardianModal(id);}
function dismissAlert(id){const a=state.alerts.find(x=>x.id===id);if(!a)return;confirmAction('DISMISS SIMULATED ALERT',`Mark “${a.title}” from ${a.source} as reviewed and dismissed? This only changes the local prototype.`, 'DISMISS ALERT',()=>{a.status='DISMISSED';state.acknowledged++;state.events.unshift({time:clock(),title:`Alert dismissed: ${a.title}`,level:'REVIEWED',source:'Admin operator'});closeModal();render();notify('ALERT MARKED AS REVIEWED');},'warn');}
function approveRecommendation(index){const rec=[['Establish alternate communication channel for Personnel-07','Risk reduction -12%'],['Dispatch nearby support team to investigate Personnel-07','Response time -18%'],['Inspect Equipment E-04 during next safe maintenance window','Failure risk -21%']][Number(index)||0];confirmAction('HUMAN APPROVAL REQUIRED',`Review the simulated recommendation: “${rec[0]}” (${rec[1]}). Approve a local demonstration-only mitigation?`, 'APPROVE SIMULATED ACTION',()=>{if(index==0){state.comm.coverage=clamp(state.comm.coverage+9);state.comm.packetLoss=Math.max(1,state.comm.packetLoss-3);const p=state.people.find(x=>x.id==='PERSONNEL-07');p.commQuality=clamp(p.commQuality+12);p.communication='FAIR';}else if(index==1){const p=state.people.find(x=>x.id==='PERSONNEL-07');p.movement='MOVING';p.heartRate=Math.max(84,p.heartRate-15);p.status='ATTENTION';}else{const e=state.equipment.find(x=>x.id==='Equipment E-04');e.temperature=Math.max(52,e.temperature-8);e.failureProbability=Math.max(18,e.failureProbability-21);}state.events.unshift({time:clock(),title:`Simulated recommendation approved: ${rec[0]}`,level:'HUMAN REVIEW',source:'Admin operator'});closeModal();derive();render();notify('SIMULATED MITIGATION APPLIED · LOCAL STATE ONLY');},'primary');}
function adminPanel(){openModal('ADMIN OPERATOR CONSOLE',`<div class="status-line"><span class="operator-avatar">AD</span><div><b>DEMO OPERATOR</b><br><span>Admin view · local simulation only</span></div></div><div class="divider"></div><div class="mini-stat-grid"><div class="mini-stat"><span>FEED STATE</span><strong style="font-size:12px">${state.livePaused?'PAUSED':'STREAMING'}</strong></div><div class="mini-stat"><span>ACTIVE ALERTS</span><strong>${state.alerts.filter(a=>a.status==='ACTIVE').length}</strong></div><div class="mini-stat"><span>APPROVALS</span><strong>${state.acknowledged}</strong></div></div><div class="quote-callout">This admin-first prototype has no login, user management or production privileges. Operator actions affect only this simulated browser session.</div>`,[{label:'Close',action:'close-modal',className:'ghost'},{label:state.livePaused?'Resume feed':'Pause feed',action:'toggle-feed-modal',className:'primary'}]);}
function handleAction(action,target){const id=target.dataset.id;switch(action){
  case'run-demo':startDemo();break;
  case'reset-sim':confirmAction('RESET SIMULATION','Restore the initial Command Center values, simulated alerts and scenario controls?','RESET SIMULATION',()=>{state=createState();closeModal();render();notify('SIMULATION RESET TO BASELINE');},'warn');break;
  case'reset-demo':state=createState();render();notify('DEMO RESET TO BASELINE');break;
  case'pause-demo':pauseDemo(true);break;case'resume-demo':pauseDemo(false);break;case'next-stage':advanceDemo();break;
  case'toggle-feed':state.livePaused=!state.livePaused;render();notify(state.livePaused?'SIMULATED FEED PAUSED':'SIMULATED FEED RESUMED');break;
  case'refresh-feed':state.lastSync=clock();state.feedTicks++;derive();render();notify('SIMULATED SIGNALS REFRESHED');break;
  case'assistant-open':state.assistantOpen=true;renderAssistant();$('#assistant-input')?.focus();break;
  case'assistant-close':state.assistantOpen=false;renderAssistant();break;
  case'close-modal':closeModal();break;
  case'confirm-local':{const fn=state.pendingConfirm;state.pendingConfirm=null;closeModal();if(fn)fn();break;}
  case'backdrop-close':if(target.classList.contains('modal-backdrop'))closeModal();break;
  case'investigate':showAlertDetail(id);break;
  case'simulate-alert':{const a=state.alerts.find(x=>x.id===id);const scenario=a?.title.toLowerCase().includes('equipment')?'equipment':a?.title.toLowerCase().includes('environment')?'environment':a?.title.toLowerCase().includes('distress')?'distress':'communication';applyScenario(scenario);break;}
  case'dismiss-alert':dismissAlert(id);break;
  case'open-guardian':closeModal();guardianModal(id||'PERSONNEL-07');break;
  case'investigate-person':investigatePerson(id);break;
  case'admin-panel':adminPanel();break;
  case'notifications':state.view='intelligence';render();notify('OPENED AI INTELLIGENCE & EVENT HISTORY');break;
  case'simulate-environment':applyEnvironment();break;
  case'reset-env':resetEnvironment();break;
  case'calculate-whatif':runWhatIf(false);break;
  case'apply-whatif':runWhatIf(true);break;
  case'intervene':confirmAction('CASCADEGUARD · HUMAN REVIEW',`Cascade risk is ${state.mission.cascadeRisk}%. Review the causal chain and approve a simulated prevention step?`,'REVIEW SIMULATED ACTION',()=>{state.comm.coverage=clamp(state.comm.coverage+8);state.comm.packetLoss=Math.max(1,state.comm.packetLoss-2);state.events.unshift({time:clock(),title:'CASCADEGUARD intervention reviewed',level:'HUMAN REVIEW',source:'Admin operator'});closeModal();derive();render();notify('SIMULATED PREVENTION APPLIED');},'warn');break;
  case'review-recommendation':approveRecommendation(target.dataset.index);break;
  case'view-evidence':showAlertDetail(state.alerts.find(a=>a.status==='ACTIVE')?.id);break;
  case'run-scenario':state.view='rescue';render();notify('SCENARIO CONTROLS READY');break;
  case'simulate-failure':confirmAction('SIMULATE EQUIPMENT FAILURE',`Apply a local thermal-degradation scenario to ${id}? Connected equipment, mission risk and response priority will update.`,'SIMULATE FAILURE',()=>{applyScenario('equipment');closeModal();},'warn');break;
  case'isolate-network':confirmAction('DEFENSIVE ISOLATION REVIEW','The simulation suggests reviewing network isolation for the unavailable communication node. This does not isolate or alter any real system.','REVIEW IN SIMULATION',()=>{state.events.unshift({time:clock(),title:'Network isolation recommendation reviewed',level:'HUMAN REVIEW',source:'CyberShield'});closeModal();notify('DEFENSIVE RECOMMENDATION REVIEWED');render();},'warn');break;
  case'open-rescue':state.view='rescue';closeModal();render();break;
  case'toggle-sidebar':$('#sidebar').classList.toggle('sidebar-open');break;
  case'toggle-feed-modal':state.livePaused=!state.livePaused;closeModal();render();break;
}}

document.addEventListener('click',event=>{
  const question=event.target.closest('[data-question]');if(question){askAssistant(question.dataset.question);return}
  const layer=event.target.closest('[data-layer]');if(layer){const k=layer.dataset.layer;state.layers[k]=!state.layers[k];render();return}
  const scenario=event.target.closest('[data-scenario]');if(scenario){applyScenario(scenario.dataset.scenario);return}
  const marker=event.target.closest('[data-marker]');if(marker){state.selected={type:marker.dataset.marker,id:marker.dataset.id};render();return}
  const person=event.target.closest('[data-person]');if(person){guardianModal(person.dataset.person);return}
  const view=event.target.closest('[data-view]');if(view){state.view=view.dataset.view;render();return}
  const action=event.target.closest('[data-action]');if(action){handleAction(action.dataset.action,action);return}
  const alertCard=event.target.closest('[data-alert]');if(alertCard){showAlertDetail(alertCard.dataset.alert);return}
});
document.addEventListener('input',event=>{
  const el=event.target;
  if(el.matches('[data-env-field]')){const key=el.dataset.envField,val=Number(el.value);if(key==='coverage'){state._pendingCoverage=val;$('#out-coverage').textContent=`${val}%`;}else{state.env[key]=val;const unit=key==='temperature'?'°C':'%';$(`#out-${key}`).textContent=`${val}${unit}`;}return}
  if(el.matches('[data-whatif]')){const key=el.dataset.whatif;state.whatIf[key]=Number(el.value);$(`#whatif-${key}`).textContent=`${el.value}%`;state.whatIf.result=null;return}
});
document.addEventListener('change',event=>{
  const el=event.target;if(el.matches('[data-env-field]')){state.beforeAfter=null;}
});
document.addEventListener('submit',event=>{if(event.target.id==='assistant-form'){event.preventDefault();const input=$('#assistant-input');askAssistant(input?.value||'');}});
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();state.assistantOpen=true;renderAssistant();$('#assistant-input')?.focus();}if(event.key==='Escape'){if($('#modal-root').innerHTML)closeModal();else if(state.assistantOpen){state.assistantOpen=false;renderAssistant();}}});

function applyDemoMetricOverrides(){
  if(state.demo.running){const i=state.demo.index;
    if(i===0){state.mission.safety=82;state.mission.teamRisk=24;state.comm.health=96;state.comm.latency=32;state.env.visibility=88;}
    if(i===1){state.mission.missionRisk=58;state.comm.health=72;}
    if(i===5)state.mission.cascadeRisk=82;
    if(i===6)state.mission.responsePriority='HIGH';
    if(i===7){state.mission.missionRisk=74;state.mission.teamRisk=51;state.mission.responsePriority='HIGH';state.comm.health=72;}
  }else if(state.demo.index===8){state.mission.safety=88;state.mission.teamRisk=31;state.mission.missionRisk=48;state.mission.responsePriority='OPTIMIZED';state.comm.coverage=90;state.comm.health=90;}
}
const baseDerive=derive;
derive=function(){baseDerive();state.comm.health=clamp(round(.9*state.comm.coverage+.1*(100-state.comm.packetLoss*2)));state.comm.latency=Math.max(24,round(30+commDegradation()*.6+state.comm.packetLoss*.9));applyDemoMetricOverrides();};
const baseDemoBanner=createDemoBanner;
createDemoBanner=function(){const html=baseDemoBanner();return state.demo.index===8?html+`<div class="attention-banner" style="margin:-4px 0 12px"><b>MISSION RISK REDUCED</b> · SENTINEL-X RESPONSE PLAN GENERATED · SEE THE RISK. UNDERSTAND THE CAUSE. SIMULATE THE FUTURE. RESPOND BEFORE IT ESCALATES.</div>`:html;};

function tick(){if(!state.livePaused){state.lastSync=clock();state.feedTicks++;if(!state.demo.running){
    const p=state.people.find(x=>x.id==='PERSONNEL-07');p.heartRate=clamp(p.heartRate+randomDelta(),65,145);p.fatigue=clamp(p.fatigue+(Math.random()>.88?1:0),20,95);
    if(state.comm.coverage>40&&state.comm.coverage<97&&Math.random()>.62)state.comm.coverage=clamp(state.comm.coverage+randomDelta(),40,98);
    state.comm.packetLoss=clamp(Math.round((state.comm.packetLoss+(Math.random()-.5)*.8)*10)/10,.5,35);
    state.env.visibility=clamp(state.env.visibility+randomDelta(),35,99);
    if(state.feedTicks%8===0){const messages=['Signal quality remained within simulated tolerance.','Digital Guardian observed a small movement variance.','Communication node heartbeat refreshed.','Environmental layer recalculated from simulated telemetry.'];state.events.unshift({time:clock(),title:messages[Math.floor(Math.random()*messages.length)],level:'INFO',source:'Simulated live feed'});state.events=state.events.slice(0,12);}
    if(state.feedTicks%24===0&&state.alerts.filter(a=>a.status==='ACTIVE').length<5){const which=state.feedTicks%48===0?'LOW':'MEDIUM';state.alerts.unshift({id:`LIVE-${Date.now()}`,severity:which,title:'Simulated telemetry update',source:'Mission feed',message:'A small signal variation was observed; risk remains under continuous review.',confidence:78+Math.floor(Math.random()*15),time:clock(),status:'ACTIVE',action:'Inspect the trend in the relevant dashboard.'});}
  }}
  if(state.demo.running&&!state.demo.paused){state.demo.elapsed+=3;if(state.demo.elapsed>=20)advanceDemo();}
  derive();render();
}

// Start at the admin-first Command Center; every view uses one local state model.
derive();render();
setInterval(tick,3000);

// Focused interaction refinements: stage progress uses real seconds, layer toggles visibly affect the map,
// and environmental sliders are committed into the same risk state only when the operator simulates.
const originalApplyEnv=applyEnvironment;
applyEnvironment=function(){
  const saved=state.envBefore||{env:{...state.env},coverage:state.comm.coverage,metrics:{team:state.mission.teamRisk,mission:state.mission.missionRisk,priority:state.mission.responsePriority}};
  if(state._pendingCoverage!==undefined)state.comm.coverage=state._pendingCoverage;
  state.env.environmentRisk=clamp(round((100-state.env.visibility)*.42+(100-state.env.terrainStability)*.26+state.env.rainfall*.18+(state.env.temperature>35?(state.env.temperature-35)*1.1:0)));
  state.env.weather=state.env.rainfall>70?'Heavy rain':state.env.rainfall>45?'Showers':'Changing';
  derive();const after={...state.env,coverage:state.comm.coverage};
  state.beforeAfter={before:{'Visibility':`${saved.env.visibility}%`,'Temperature':`${saved.env.temperature}°C`,'Terrain stability':`${saved.env.terrainStability}%`,'Environment risk':`${saved.env.environmentRisk}%`,'Communication coverage':`${saved.coverage}%`,'Team risk':`${saved.metrics.team}%`,'Mission risk':`${saved.metrics.mission}%`,'Response priority':saved.metrics.priority},after:{'Visibility':`${after.visibility}%`,'Temperature':`${after.temperature}°C`,'Terrain stability':`${after.terrainStability}%`,'Environment risk':`${after.environmentRisk}%`,'Communication coverage':`${after.coverage}%`,'Team risk':`${state.mission.teamRisk}%`,'Mission risk':`${state.mission.missionRisk}%`,'Response priority':state.mission.responsePriority}};
  delete state._pendingCoverage;state.envBefore=null;state.events.unshift({time:clock(),title:'Environmental simulation recalculated',level:'SIMULATION',source:'Digital twin'});render();notify('ENVIRONMENT SIMULATED · LINKED RISKS RECALCULATED');
};
const originalResetEnvironment=resetEnvironment;
resetEnvironment=function(){state.env={visibility:78,temperature:31,rainfall:28,terrainStability:78,weather:'Changing',environmentRisk:24};state.comm.coverage=87;delete state._pendingCoverage;state.envBefore=null;state.beforeAfter=null;derive();render();notify('ENVIRONMENT SCENARIO RESET');};
const originalDemoBannerFixed=createDemoBanner;
createDemoBanner=function(){const stageNamesFixed=['Normal mission','Communication anomaly','Predictive equipment warning','Environment change','Silent distress','CASCADEGUARD','Rescue response brain','What-If: restore communications','Final Command Center'];const stage=state.demo.index+1;const seconds=state.demo.index*20+state.demo.elapsed;const pct=state.demo.index===8&&!state.demo.running?100:state.demo.running?Math.min(100,Math.floor(seconds/180*100)):0;const mm=String(Math.floor(seconds/60)).padStart(2,'0'),ss=String(seconds%60).padStart(2,'0');return `<div class="demo-banner fade-in"><div class="demo-stage-icon">${state.demo.running?'▶':'✓'}</div><div class="demo-stage-copy"><strong>DEMO MODE · STAGE ${stage} OF 9 — ${stageNamesFixed[state.demo.index]||'Complete'}</strong><span>${state.demo.running?'Scripted safety scenario · simulated data only':'Scenario complete · review the updated mission state'}</span></div><div class="demo-progress"><div class="demo-progress-top"><span>${pct}% COMPLETE</span><span>${state.demo.index===8&&!state.demo.running?'03:00':`${mm}:${ss}`}</span></div><div class="meter-line"><span style="width:${pct}%"></span></div></div><button class="btn small ghost" data-action="${state.demo.running?(state.demo.paused?'resume-demo':'pause-demo'):'reset-demo'}">${state.demo.running?(state.demo.paused?'RESUME':'PAUSE'):'RESET'}</button>${state.demo.running?'<button class="btn small ghost" data-action="next-stage">NEXT</button>':''}</div>${state.demo.index===8&&!state.demo.running?'<div class="attention-banner" style="margin:-4px 0 12px"><b>MISSION RISK REDUCED</b> · SENTINEL-X RESPONSE PLAN GENERATED · SEE THE RISK. UNDERSTAND THE CAUSE. SIMULATE THE FUTURE. RESPOND BEFORE IT ESCALATES.</div>':''}`;};
