// Requirement-aligned refinements: scenario values remain stateful and explainable across every view.
const missionExplanationBase=missionExplanation;
missionExplanation=function(){if(!state.demo.running&&state.demo.index===0&&state.comm.coverage>=75&&state.env.environmentRisk<=35)return 'Mission risk increased by 11% because Personnel-07 showed elevated physiological stress while communication quality degraded. At the same time, Equipment E-04 entered a warning state and environmental visibility decreased. This is an AI-generated simulation, not a validated forecast.';return missionExplanationBase();};
const priorityIncidentsBase=priorityIncidents;
priorityIncidents=function(){const rows=priorityIncidentsBase();const node=rows.find(x=>x.id==='Communication Node C-04');if(node){node.severity='HIGH';node.score=Math.min(99,round(58+commDegradation()));}return rows.sort((a,b)=>b.score-a.score);};
const calculateWhatIfBase=calculateWhatIf;
calculateWhatIf=function(){const base={mission:state.mission.missionRisk,team:state.mission.teamRisk,priority:state.mission.responsePriority};const averageEquipment=state.equipment.reduce((a,e)=>a+e.health,0)/state.equipment.length;const commDrop=state.comm.coverage-state.whatIf.communication;const visibilityDrop=state.env.visibility-state.whatIf.visibility;const equipmentDrop=averageEquipment-state.whatIf.equipment;const teamDelta=round(.37*commDrop+.26*visibilityDrop+.11*equipmentDrop);const team=clamp(base.team+teamDelta);const missionDelta=round(.58*teamDelta+.35*commDrop+.20*visibilityDrop+.08*equipmentDrop);const mission=clamp(base.mission+missionDelta);const priority=mission>=68?'CRITICAL':mission>=50?'HIGH':mission>=32?'MEDIUM':'LOW';state.whatIf.result={before:{'Mission Risk':`${base.mission}%`,'Team Risk':`${base.team}%`,'Response Priority':base.priority},after:{'Mission Risk':`${mission}%`,'Team Risk':`${team}%`,'Response Priority':priority},explanation:commDrop>0?'The increase is primarily caused by communication degradation combined with reduced visibility.':missionDelta<0?'Restoring communications and visibility reduces modeled mission risk.':'The simulation shows a smaller change under the current input values.',reduction:base.mission-mission};state._whatIfOld={coverage:state.comm.coverage,environment:state.env.environmentRisk,equipment:state.equipment.map(e=>e.health)};};
const deriveBeforeAppliedWhatIf=derive;
derive=function(){deriveBeforeAppliedWhatIf();const b=state.whatIf?.appliedBase;if(state.whatIf?.applied&&b&&!state.demo.running){const commDrop=b.coverage-state.comm.coverage,visibilityDrop=b.visibility-state.env.visibility,equipmentDrop=b.equipment-state.equipment.reduce((a,e)=>a+e.health,0)/state.equipment.length;const teamDelta=round(.37*commDrop+.26*visibilityDrop+.11*equipmentDrop);state.mission.teamRisk=clamp(b.team+teamDelta);const missionDelta=round(.58*teamDelta+.35*commDrop+.20*visibilityDrop+.08*equipmentDrop);state.mission.missionRisk=clamp(b.mission+missionDelta);state.mission.safety=clamp(round(100-state.mission.missionRisk*.43));state.mission.responsePriority=state.mission.missionRisk>=68?'CRITICAL':state.mission.missionRisk>=50?'HIGH':state.mission.missionRisk>=32?'MEDIUM':'LOW';}};
const runWhatIfBase=runWhatIf;
runWhatIf=function(apply=false){if(apply){state.whatIf.appliedBase={mission:state.mission.missionRisk,team:state.mission.teamRisk,priority:state.mission.responsePriority,coverage:state.comm.coverage,visibility:state.env.visibility,equipment:state.equipment.reduce((a,e)=>a+e.health,0)/state.equipment.length};state.whatIf.applied=true;state.demo.running=false;state.demo.paused=false;}return runWhatIfBase(apply);};
