renderPersonnel=function(){let html=renderPersonnelBase();html=html.replace('TEAM ALPHA · derived from shared state','TEAM ALPHA · RISK BANDS BY SCORE');html=html.replace('<div class="quote-callout">One elevated individual signal can affect overall team risk when communications are degraded.</div>',`<div class="team-network"><span>SIMULATED TEAM SIGNAL NETWORK</span><svg viewBox="0 0 320 74" role="img" aria-label="Team signal dependencies converge on Personnel-07 and the team risk score"><path d="M42 16 155 37M42 58 155 37M278 16 165 37M278 58 165 37M160 37 160 67"/><circle cx="42" cy="16" r="8"/><circle cx="42" cy="58" r="8"/><circle cx="278" cy="16" r="8"/><circle cx="278" cy="58" r="8"/><circle class="critical-node" cx="160" cy="37" r="12"/><circle class="team-node" cx="160" cy="67" r="7"/><text x="7" y="11">HR</text><text x="7" y="74">COMMS</text><text x="258" y="11">FATIGUE</text><text x="259" y="74">MOVEMENT</text></svg><small>Personnel-07 weak signals contribute to combined team risk.</small></div><div class="quote-callout">One elevated individual signal can affect overall team risk when communications are degraded.</div>`);const counts={normal:state.people.filter(p=>p.risk<35).length,attention:state.people.filter(p=>p.risk>=35&&p.risk<65).length,critical:state.people.filter(p=>p.risk>=65).length};return html.replace('● 19 Normal',`● ${counts.normal} Normal`).replace('● 4 Attention',`● ${counts.attention} Attention`).replace('● 1 Critical signal',`● ${counts.critical} Critical signal`);};
