// Admin personalization and local-only emergency broadcast simulation.
const UI_THEME_KEY='sentinelx.theme.v1';
const UI_WIDGETS_KEY='sentinelx.dashboard-widgets.v1';
const dashboardWidgetDefinitions=[
  {key:'kpis',label:'Safety & live KPI strip',detail:'Mission safety, team risk, personnel and system readiness.'},
  {key:'map',label:'Mission map',detail:'Simulated personnel, asset and coverage layers.'},
  {key:'alerts',label:'Live alert center',detail:'Prioritized local alerts and review actions.'},
  {key:'risk',label:'Risk explanation',detail:'Evidence and factor contributions for the mission score.'},
  {key:'cascade',label:'CASCADEGUARD',detail:'Causal chain and early-warning intervention.'},
  {key:'response',label:'Response priorities',detail:'Ranked human-review decision support.'},
  {key:'recommendations',label:'Recommended actions',detail:'Simulated mitigations requiring operator approval.'}
];
const defaultDashboardWidgets=Object.fromEntries(dashboardWidgetDefinitions.map(item=>[item.key,true]));
function readStoredPreference(key){try{return window.localStorage.getItem(key)}catch{return null}}
function writeStoredPreference(key,value){try{window.localStorage.setItem(key,value)}catch{}}
function storedTheme(){return readStoredPreference(UI_THEME_KEY)==='light'?'light':'dark'}
function storedWidgets(){let saved={};try{saved=JSON.parse(readStoredPreference(UI_WIDGETS_KEY)||'{}')||{}}catch{saved={}}const result={...defaultDashboardWidgets};for(const item of dashboardWidgetDefinitions)if(typeof saved[item.key]==='boolean')result[item.key]=saved[item.key];return result}
const createStateWithAdminPreferences=createState;
createState=function(){const next=createStateWithAdminPreferences();next.uiPrefs={theme:storedTheme(),widgets:storedWidgets()};next.activeSOS=null;return next};
state.uiPrefs={theme:storedTheme(),widgets:storedWidgets()};
state.activeSOS=null;
function saveThemePreference(theme){writeStoredPreference(UI_THEME_KEY,theme)}
function saveWidgetPreferences(){writeStoredPreference(UI_WIDGETS_KEY,JSON.stringify(state.uiPrefs.widgets))}
function applyTheme(theme=state.uiPrefs.theme){const next=theme==='light'?'light':'dark';state.uiPrefs.theme=next;if(document.body)document.body.dataset.theme=next;const button=$('[data-action="toggle-theme"]');if(button){const light=next==='light';button.textContent=light?'◐':'☼';button.setAttribute('aria-label',`Switch to ${light?'dark':'light'} mode`);button.setAttribute('aria-pressed',String(light));button.title=`${light?'LIGHT':'DARK'} MODE · click to switch`}}
function applyDashboardVisibility(){if(!document.body)return;document.body.dataset.hiddenWidgets=dashboardWidgetDefinitions.filter(item=>state.uiPrefs.widgets[item.key]===false).map(item=>item.key).join(' ')}
function setTheme(theme){applyTheme(theme);saveThemePreference(state.uiPrefs.theme);notify(`APPEARANCE SET TO ${state.uiPrefs.theme.toUpperCase()} MODE`)}

function wrapWidgetDiv(html,key){const start=html.indexOf('<div class="kpi-grid"');if(start<0)return html;const token=/<\/?div\b[^>]*>/gi;token.lastIndex=start;let depth=0,end=-1,match;while((match=token.exec(html))){if(/^<\//.test(match[0]))depth--;else depth++;if(depth===0){end=token.lastIndex;break}}if(end<0)return html;return html.slice(0,start)+`<div class="dashboard-widget" data-dashboard-widget="${key}">`+html.slice(start,end)+'</div>'+html.slice(end)}
function wrapWidgetPanel(html,heading,key){const at=html.indexOf(heading);if(at<0)return html;const start=html.lastIndexOf('<section',at),close=html.indexOf('</section>',at);if(start<0||close<0)return html;const end=close+'</section>'.length;return html.slice(0,start)+`<div class="dashboard-widget" data-dashboard-widget="${key}">`+html.slice(start,end)+'</div>'+html.slice(end)}
const renderCommandBeforeWidgetControls=renderCommand;
renderCommand=function(){let html=renderCommandBeforeWidgetControls();html=wrapWidgetDiv(html,'kpis');for(const [heading,key] of [['LIVE MISSION MAP','map'],['LIVE AI ALERTS','alerts'],['WHY RISK IS CHANGING','risk'],['CASCADEGUARD','cascade'],['RESPONSE PRIORITY','response'],['RECOMMENDED ACTIONS','recommendations']])html=wrapWidgetPanel(html,heading,key);html=html.replace('<span class="ribbon-spacer"></span>','<button class="btn small ghost widget-customize" data-action="customize-dashboard">⚙ CUSTOMIZE WIDGETS</button><span class="ribbon-spacer"></span>');return html};
const renderMapBeforeSOS=renderMapPanel;
renderMapPanel=function(context='command',right=''){let html=renderMapBeforeSOS(context,right);const seam='</div><div class="map-legend">',at=html.indexOf(seam);if(at>=0){const incident=state.activeSOS;const active=incident?.status==='ACTIVE';const badge=incident?`<div class="sos-active-banner ${active?'is-active':'is-resolved'}" role="status"><span class="sos-pulse"></span><strong>SIMULATED SOS ${active?'ACTIVE':'RESOLVED'}</strong><span>${safeText(incident.origin)} · ${safeText(incident.time)}</span>${active?'<button class="btn small danger" data-action="resolve-sos">MARK RESOLVED</button>':''}</div>`:'';const trigger=`<button class="sos-map-button" data-action="trigger-sos" ${active?'disabled aria-disabled="true" title="Resolve the active simulated SOS before starting another"':'aria-label="Trigger a simulated SOS emergency broadcast" title="Open local SOS simulation"'}>${active?'SOS ACTIVE':'⚠ SIMULATE SOS'}</button>`;html=html.slice(0,at)+badge+trigger+html.slice(at);if(active){const origin=idLabel(incident.origin);const markerPattern=new RegExp(`(<button class="map-marker person[^"]*)"([^>]*data-marker="person" data-id="${origin}")`);html=html.replace(markerPattern,'$1 sos-origin$2')}}return html};

function openDashboardCustomizer(){const rows=dashboardWidgetDefinitions.map(item=>`<label class="widget-setting"><input type="checkbox" data-dashboard-widget-toggle="${item.key}" ${state.uiPrefs.widgets[item.key]?'checked':''}><span><strong>${item.label}</strong><small>${item.detail}</small></span></label>`).join('');openModal('CUSTOMIZE ADMIN DASHBOARD',`<p>Choose which panels appear in the Command Center. Changes apply immediately and are saved in this browser only.</p><div class="widget-settings">${rows}</div><div class="attention-banner">Hiding a panel changes the layout only. Simulated monitoring, alerts and scenario calculations continue unchanged.</div>`,[{label:'RESTORE DEFAULT',action:'reset-dashboard',className:'ghost'},{label:'DONE',action:'close-modal',className:'primary'}])}
const adminPanelBeforeCustomization=adminPanel;
adminPanel=function(){adminPanelBeforeCustomization();const modal=$('#modal-root');if(modal?.innerHTML.includes('</footer>'))modal.innerHTML=modal.innerHTML.replace('</footer>','<button class="btn primary" data-action="customize-dashboard">CUSTOMIZE DASHBOARD</button></footer>')};

function openSOSModal(){if(state.activeSOS?.status==='ACTIVE'){notify('A SIMULATED SOS IS ALREADY ACTIVE · RESOLVE OR RESET IT FIRST');return}const preferred=state.selected?.type==='person'&&state.people.some(person=>person.id===state.selected.id)?state.selected.id:'PERSONNEL-07';const options=state.people.map(person=>`<option value="${person.id}" ${person.id===preferred?'selected':''}>${person.id} · Sector ${person.location.x>55?'B':'A'} · current risk ${person.risk}%</option>`).join('');openModal('SIMULATE SOS / EMERGENCY BROADCAST',`<div class="sos-confirmation"><span class="sos-icon">SOS</span><div><strong>LOCAL SIMULATION ONLY</strong><p>This demo will not transmit a message, contact a responder, or connect to a real person or system.</p></div></div><label class="sos-field" for="sos-origin">Simulated origin<select id="sos-origin">${options}</select></label><label class="sos-field" for="sos-message">Broadcast message<input id="sos-message" type="text" maxlength="140" value="Assistance requested — initiate a simulated welfare check." autocomplete="off"></label><div class="attention-banner">Confirm to add a timestamped simulated CRITICAL alert, update this map marker and elevate the local response priority.</div>`,[{label:'CANCEL',action:'close-modal',className:'ghost'},{label:'TRIGGER SIMULATED SOS',action:'send-sos',className:'danger'}])}
function sendSimulatedSOS(){if(state.activeSOS?.status==='ACTIVE'){closeModal();notify('A SIMULATED SOS IS ALREADY ACTIVE');return}const originId=$('#sos-origin')?.value||'PERSONNEL-07';const person=state.people.find(item=>item.id===originId);if(!person){notify('CHOOSE A SIMULATED PERSONNEL ORIGIN');return}const message=($('#sos-message')?.value||'Assistance requested — initiate a simulated welfare check.').trim().slice(0,140)||'Assistance requested — initiate a simulated welfare check.';const previous={status:person.status,heartRate:person.heartRate,fatigue:person.fatigue,movement:person.movement,communication:person.communication,commQuality:person.commQuality};const timestamp=clock(),alertId=`SOS-${Date.now()}`;person.status='CRITICAL';person.heartRate=Math.max(person.heartRate,118);person.fatigue=Math.max(person.fatigue,74);person.movement='NO MOVEMENT';person.communication='WEAK';person.commQuality=Math.min(person.commQuality,18);state.activeSOS={alertId,origin:person.id,message,time:timestamp,status:'ACTIVE',previous};state.alerts.unshift({id:alertId,severity:'CRITICAL',title:'SIMULATED SOS BROADCAST',source:person.id,message,confidence:99,time:timestamp,status:'ACTIVE',action:'Operator-triggered local SOS simulation. Review origin and decide whether to mark resolved.'});state.alerts=state.alerts.slice(0,30);state.events.unshift({time:timestamp,title:`Simulated SOS broadcast · ${person.id}`,level:'CRITICAL',source:'Admin operator'});state.events=state.events.slice(0,12);state.selected={type:'person',id:person.id};state.lastSync=timestamp;closeModal();derive();render();notify(`SIMULATED SOS ACTIVE · ${person.id} · NO REAL MESSAGE SENT`)}
function confirmResolveSOS(){const incident=state.activeSOS;if(!incident||incident.status!=='ACTIVE')return;confirmAction('RESOLVE SIMULATED SOS',`Mark the simulated SOS from ${incident.origin} as resolved and restore that person's pre-scenario values?`,'RESOLVE LOCAL SOS',()=>{const person=state.people.find(item=>item.id===incident.origin);if(person&&incident.previous)Object.assign(person,incident.previous);const alert=state.alerts.find(item=>item.id===incident.alertId);if(alert)alert.status='RESOLVED';incident.status='RESOLVED';incident.resolvedAt=clock();state.events.unshift({time:incident.resolvedAt,title:`Simulated SOS resolved · ${incident.origin}`,level:'RESOLVED',source:'Admin operator'});derive();render();notify('SIMULATED SOS RESOLVED · LOCAL STATE RESTORED')},'primary')}
const deriveBeforeSOS=derive;
derive=function(){deriveBeforeSOS();if(state.activeSOS?.status==='ACTIVE')state.mission.responsePriority='CRITICAL'};
const handleActionBeforeAdminControls=handleAction;
handleAction=function(action,target){if(action==='toggle-theme'){setTheme(state.uiPrefs.theme==='dark'?'light':'dark');return}if(action==='customize-dashboard'){openDashboardCustomizer();return}if(action==='reset-dashboard'){state.uiPrefs.widgets={...defaultDashboardWidgets};saveWidgetPreferences();closeModal();render();notify('DEFAULT DASHBOARD WIDGETS RESTORED');return}if(action==='trigger-sos'){openSOSModal();return}if(action==='send-sos'){sendSimulatedSOS();return}if(action==='resolve-sos'){confirmResolveSOS();return}handleActionBeforeAdminControls(action,target)};
document.addEventListener('change',event=>{const input=event.target;if(input.matches('[data-dashboard-widget-toggle]')){const key=input.dataset.dashboardWidgetToggle;if(Object.hasOwn(defaultDashboardWidgets,key)){state.uiPrefs.widgets[key]=input.checked;saveWidgetPreferences();applyDashboardVisibility();render();notify(`${dashboardWidgetDefinitions.find(item=>item.key===key)?.label.toUpperCase()} ${input.checked?'SHOWN':'HIDDEN'}`)}}});
const renderBeforeAdminPreferences=render;
render=function(){renderBeforeAdminPreferences();applyTheme(state.uiPrefs.theme);applyDashboardVisibility()};
applyTheme();
applyDashboardVisibility();
render();
